+        />
+      ),
+    },
+    'needs-test': {
+      variant: 'default',
+      text: t('Test me'),
+      icon: <TriangleAlert className="size-3" />,
+    },
+    untested: {
+      variant: 'default',
+      text: t('Test me'),
+      icon: <TriangleAlert className="size-3" />,
+    },
+    tested: {
+      variant: 'success',
+      text: t('Tested'),
+      icon: (
+        <StepStatusIcon
+          status={StepOutputStatus.SUCCEEDED}
+          size="3"
+          hideTooltip={true}
+        />
+      ),
+    },
+  };
+  const status: DraftStepStatus = useMemo(() => {
+    if (isSkipped) return 'skipped';
+    if (!isStepValid) return 'invalid';
+    if (isBeingTested) return 'testing';
+
+    if (isNil(lastTestDate)) {
+      return 'untested';
+    }
+    if (lastUpdatedDate > lastTestDate) {
+      return 'needs-test';
+    }
+    if (hasError) return 'failed';
+
+    return 'tested';
+  }, [
+    isSkipped,
+    isStepValid,
+    isBeingTested,
+    hasError,
+    lastTestDate,
+    lastUpdatedDate,
+  ]);
+
+  if (!isNil(run) || stepType === FlowTriggerType.EMPTY || !isInDraft) {
+    return null;
+  }
+
+  const config = draftStatusConfig[status];
+
+  return (
+    <div className="absolute right-[1px] h-[20px] -top-[28px]">
+      <Tooltip>
+        <TooltipTrigger asChild>
+          <div
+            className={flowRunUtils.getStatusContainerClassName(
+              config.variant,
+              true,
+            )}
+          >
+            {config.icon}
+            <div>{config.text}</div>
+          </div>
+        </TooltipTrigger>
+        {status === 'untested' && (
+          <TooltipContent>
+            {t('This step has not been tested yet')}
+          </TooltipContent>
+        )}
+        {status === 'needs-test' && (
+          <TooltipContent>
+            {t('This step has been updated since the last test')}
+          </TooltipContent>
+        )}
+      </Tooltip>
+    </div>
+  );
+};
+
+ApStepNodeStatusInDraft.displayName = 'ApStepNodeStatusInDraft';
+export { ApStepNodeStatusInDraft };

