+import { PieceAuth, Property } from '@activepieces/pieces-framework';
+import { AppConnectionType } from '@activepieces/shared';
+import { TeableClient } from './common/client';
+import { TEABLE_CLOUD_URL } from './common/constants';
+
+export const TeableAuth = [
+  PieceAuth.OAuth2({
+    description: 'Connect your Teable account using OAuth2 (Teable Cloud only).',
+    authUrl: 'https://app.teable.ai/api/oauth/authorize',
+    tokenUrl: 'https://app.teable.ai/api/oauth/access_token',
+    required: true,
+    scope: [
+      'base|read',
+      'table|read',
+      'field|read',
+      'record|read',
+      'record|create',
+      'record|update',
+      'record|delete',
+    ],
+  }),
+  PieceAuth.CustomAuth({
+    displayName: 'Personal Access Token',
+    description: `
+Authenticate using a Teable Personal Access Token. Also use this option for self-hosted instances.
+
+To obtain your token:
+1. Log in to your Teable account.
+2. Click your profile icon (top-right corner).
+3. Go to **Settings** > **Personal Access Token**.
+4. Click **New Token**, set a name and the required scopes.
+5. Copy and save the generated token.
+    `,
+    required: true,
+    props: {
+      token: PieceAuth.SecretText({
+        displayName: 'Personal Access Token',
+        description: 'Your Teable personal access token.',
+        required: true,
+      }),
+      baseUrl: Property.ShortText({
+        displayName: 'Base URL',
+        description:
+          'Teable Cloud: https://app.teable.ai — for self-hosted, enter your own domain.',
+        required: false,
+      }),
+    },
+    validate: async ({ auth }) => {
+      try {
+        const client = new TeableClient(
+          auth.token,
+          auth.baseUrl || TEABLE_CLOUD_URL
+        );
+        await client.listBases();
+        return { valid: true };
+      } catch (e) {
+        return {
+          valid: false,
+          error: e instanceof Error ? e.message : 'Invalid credentials. Check your token and Base URL.',
+        };
+      }
+    },
+  }),
+];
+
+export type TeableAuthValue = {
+  type: AppConnectionType.OAUTH2;
+  access_token: string;
+} | {
+  type: AppConnectionType.CUSTOM_AUTH;
+  props: { token: string; baseUrl?: string };
+};
+
+export function getTeableToken(auth: TeableAuthValue): string {
+  if (auth.type === AppConnectionType.OAUTH2) {
+    return auth.access_token;
+  }
+  return auth.props.token;
+}
+
+export function getTeableBaseUrl(auth: TeableAuthValue): string {
+  if (auth.type === AppConnectionType.OAUTH2) {
+    return TEABLE_CLOUD_URL;
+  }
+  return auth.props.baseUrl || TEABLE_CLOUD_URL;
+}

diff --git a/packages/pieces/community/teable/src/lib/common/client.ts b/packages/pieces/community/teable/src/lib/common/client.ts
new file mode 100644
index 0000000000000000000000000000000000000000..c9c5a3ff293d159b9c9fc1259dff96ba5d9b5766
--- /dev/null
+++ b/packages/pieces/community/teable/src/lib/common/client.ts
@@ -0,0 +1,219 @@
+import {
+  HttpMessageBody,
+  HttpMethod,
+  QueryParams,
+  AuthenticationType,
+  httpClient,
+} from '@activepieces/pieces-common';
+import { TEABLE_CLOUD_URL } from './constants';
+
+
+function emptyValueFilter(
+  accessor: (key: string) => any
+): (key: string) => boolean {
+  return (key: string) => {
+    const val = accessor(key);
+    return (
+      val !== null &&
+      val !== undefined &&
+      (typeof val !== 'string' || val.length > 0) &&
+      (!Array.isArray(val) || val.length > 0)
+    );
+  };
+}
+
+export function prepareQuery(request?: Record<string, any>): QueryParams {
+  const params: QueryParams = {};
+  if (!request) return params;
+  Object.keys(request)
+    .filter(emptyValueFilter((k) => request[k]))
+    .forEach((k: string) => {
+      const val = (request as Record<string, any>)[k];
+      params[k] = Array.isArray(val) ? val : val.toString();
+    });
+  return params;
+}
+
+
+
+export class TeableClient {
+  private readonly apiBase: string;
+
+  constructor(
+    private token: string,
+    teableUrl: string = TEABLE_CLOUD_URL
+  ) {
+    this.apiBase = `${teableUrl}/api`;
+  }
+
+  async makeRequest<T extends HttpMessageBody>(
+    method: HttpMethod,
+    resourceUri: string,
+    query?: QueryParams,
+    body: any | undefined = undefined
+  ): Promise<T> {
+    const res = await httpClient.sendRequest<T>({
+      method,
+      url: this.apiBase + resourceUri,
+      authentication: {
+        type: AuthenticationType.BEARER_TOKEN,
+        token: this.token,
+      },
+      queryParams: query,
+      body: body,
+    });
+
+    return res.body;
+  }
+
+  /**
+   * GET /api/base/access/all
+   * Returns all bases the token has access to.
+   * @see https://help.teable.ai/en/api-reference/base/get-baseaccessall
+   */
+  async listBases() {
+    return await this.makeRequest<
+      {
+        id: string;
+        name: string;
+        spaceId: string;
+        icon: string | null;
+        role: string;
+      }[]
+    >(HttpMethod.GET, '/base/access/all');
+  }
+
+  /**
+   * GET /api/base/{baseId}/table
+   * Returns all tables in the given base.
+   * @see https://help.teable.ai/en/api-reference/table/list-tables
+   */
+  async listTables(baseId: string) {
+    return await this.makeRequest<
+      {
+        id: string;
+        name: string;
+        dbTableName: string;
+        description?: string;
+        icon?: string;
+        order: number;
+        defaultViewId?: string;
+      }[]
+    >(HttpMethod.GET, `/base/${baseId}/table`);
+  }
+
+  /**
+   * GET /api/table/{tableId}/field
+   * Returns all fields in the given table.
+   * @see https://help.teable.ai/en/api-reference/field/list-fields
+   */
+  async listFields(tableId: string) {
+    return await this.makeRequest<
+      {
+        id: string;
+        name: string;
+        type: string;
+        isComputed?: boolean;
+        isPrimary?: boolean;
+        options?: {
+          choices?: { id: string; name: string; color?: string }[];
+          [key: string]: unknown;
+        };
+      }[]
+    >(HttpMethod.GET, `/table/${tableId}/field`);
+  }
+
+  /**
+   * GET /api/table/{tableId}/record/{recordId}
+   * Retrieves a single record by its ID.
+   * @see https://help.teable.ai/en/api-reference/record/get-record
+   */
+  async getRecord(
+    tableId: string,
+    recordId: string,
+    query?: QueryParams
+  ) {
+    return await this.makeRequest<{
+      id: string;
+      fields: Record<string, unknown>;
+      name: string;
+      autoNumber: number;
+      createdTime: string;
+      lastModifiedTime: string;
+      createdBy: string;
+      lastModifiedBy: string;
+      permissions: Record<string, unknown>;
+    }>(HttpMethod.GET, `/table/${tableId}/record/${recordId}`, query);
+  }
+
+  /**
+   * GET /api/table/{tableId}/record
+   * Retrieves a list of records with support for filtering, sorting, and pagination.
+   * @see https://help.teable.ai/en/api-reference/record/list-records
+   */
+  async listRecords(
+    tableId: string,
+    query?: QueryParams
+  ) {
+    return await this.makeRequest<{
+      records: {
+        id: string;
+        fields: Record<string, unknown>;
+      }[];
+    }>(HttpMethod.GET, `/table/${tableId}/record`, query);
+  }
+
+  /**
+   * POST /api/table/{tableId}/record
+   * Creates one or more records.
+   */
+  async createRecord(tableId: string, request: object) {
+    return await this.makeRequest(
+      HttpMethod.POST,
+      `/table/${tableId}/record`,
+      undefined,
+      request
+    );
+  }
+
+  /**
+   * DELETE /api/table/{tableId}/record/{recordId}
+   * Deletes a single record.
+   */
+  async deleteRecord(tableId: string, recordId: string) {
+    return await this.makeRequest(
+      HttpMethod.DELETE,
+      `/table/${tableId}/record/${recordId}`
+    );
+  }
+
+  /**
+   * PATCH /api/table/{tableId}/record/{recordId}
+   * Updates a single record.
+   */
+  async updateRecord(tableId: string, recordId: string, request: object) {
+    return await this.makeRequest(
+      HttpMethod.PATCH,
+      `/table/${tableId}/record/${recordId}`,
+      undefined,
+      request
+    );
+  }
+
+  /**
+   * POST /api/table/{tableId}/record/{recordId}/{fieldId}/uploadAttachment
+   * Uploads a file as an attachment to a specific field in a record.
+   */
+  async uploadAttachment(tableId: string, recordId: string, fieldId: string, form: FormData) {
+    const res = await httpClient.sendRequest({
+      method: HttpMethod.POST,
+      url: `${this.apiBase}/table/${tableId}/record/${recordId}/${fieldId}/uploadAttachment`,
+      authentication: {
+        type: AuthenticationType.BEARER_TOKEN,
+        token: this.token,
+      },
+      body: form,
+    });
+    return res.body;
+  }
+}

diff --git a/packages/pieces/community/teable/src/lib/common/index.ts b/packages/pieces/community/teable/src/lib/common/index.ts
new file mode 100644
index 0000000000000000000000000000000000000000..78d0c6da074c2b3d2d6fdd1ae2eee39705ba9cd7
--- /dev/null
+++ b/packages/pieces/community/teable/src/lib/common/index.ts
@@ -0,0 +1,139 @@
+import { DynamicPropsValue, Property } from '@activepieces/pieces-framework';
+import { TeableAuth, TeableAuthValue, getTeableToken, getTeableBaseUrl } from '../auth';
+import { TeableClient } from './client';
+import { TeableComputedFieldTypes, TeableFieldType } from './constants';
+
+export function makeClient(auth: TeableAuthValue) {
+	return new TeableClient(
+		getTeableToken(auth),
+		getTeableBaseUrl(auth)
+	);
+}
+
+export const TeableCommon = {
+	base_id: Property.Dropdown({
+		auth: TeableAuth,
+		displayName: 'Base',
+		required: true,
+		refreshers: [],
+		options: async ({ auth }) => {
+			if (!auth) {
+				return { disabled: true, options: [], placeholder: 'Connect your account first.' };
+			}
+			const client = makeClient(auth as TeableAuthValue);
+			const bases = await client.listBases();
+			return {
+				disabled: false,
+				options: bases.map((b) => ({ label: b.name, value: b.id })),
+			};
+		},
+	}),
+	table_id: Property.Dropdown({
+		auth: TeableAuth,
+		displayName: 'Table',
+		description: 'The table inside the selected base.',
+		required: true,
+		refreshers: ['base_id'],
+		options: async ({ auth, base_id }) => {
+			if (!auth || !base_id) {
+				return { disabled: true, options: [], placeholder: 'Select a base first.' };
+			}
+			const client = makeClient(auth as TeableAuthValue);
+			const tables = await client.listTables(base_id as string);
+			return {
+				disabled: false,
+				options: tables.map((t) => ({ label: t.name, value: t.id })),
+			};
+		},
+	}),
+	record_id: Property.Dropdown({
+		auth: TeableAuth,
+		displayName: 'Record',
+		description: 'The record to act on.',
+		required: true,
+		refreshers: ['table_id'],
+		options: async ({ auth, table_id }) => {
+			if (!auth || !table_id) {
+				return { disabled: true, options: [], placeholder: 'Select a table first.' };
+			}
+			const client = makeClient(auth as TeableAuthValue);
+			const response = await client.listRecords(table_id as string);
+			return {
+				disabled: false,
+				options: response.records.map((r) => {
+					const primaryValue = Object.values(r.fields)[0];
+					const label = primaryValue !== undefined && primaryValue !== null && primaryValue !== ''
+						? String(primaryValue)
+						: r.id;
+					return { label, value: r.id };
+				}),
+			};
+		},
+	}),
+	fields: Property.DynamicProperties({
+		auth: TeableAuth,
+		displayName: 'Fields',
+		description: 'The fields to add to the record.',
+		required: true,
+		refreshers: ['auth', 'table_id'],
+		props: async ({ auth, table_id }) => {
+			if (!auth || !table_id) return {};
+
+			const client = makeClient(auth as TeableAuthValue);
+			const fields = await client.listFields(table_id as string);
+
+			const props: DynamicPropsValue = {};
+
+			for (const field of fields) {
+				// Skip computed / read-only fields
+				if (field.isComputed || TeableComputedFieldTypes.includes(field.type)) {
+					continue;
+				}
+
+				const choices = field.options?.choices ?? [];
+
+				switch (field.type as TeableFieldType) {
+					case TeableFieldType.CHECKBOX:
+						props[field.name] = Property.Checkbox({ displayName: field.name, required: false });
+						break;
+					case TeableFieldType.NUMBER:
+					case TeableFieldType.RATING:
+						props[field.name] = Property.Number({ displayName: field.name, required: false });
+						break;
+					case TeableFieldType.DATE:
+						props[field.name] = Property.DateTime({ displayName: field.name, required: false });
+						break;
+					case TeableFieldType.LONG_TEXT:
+						props[field.name] = Property.LongText({ displayName: field.name, required: false });
+						break;
+					case TeableFieldType.MULTIPLE_SELECT:
+						props[field.name] = Property.StaticMultiSelectDropdown({
+							displayName: field.name,
+							required: false,
+							options: { options: choices.map((c) => ({ label: c.name, value: c.name })) },
+						});
+						break;
+					case TeableFieldType.SINGLE_SELECT:
+						props[field.name] = Property.StaticDropdown({
+							displayName: field.name,
+							required: false,
+							options: { options: choices.map((c) => ({ label: c.name, value: c.name })) },
+						});
+						break;
+					case TeableFieldType.LINK:
+					case TeableFieldType.USER:
+						props[field.name] = Property.Array({ displayName: field.name, required: false });
+						break;
+					case TeableFieldType.SINGLE_LINE_TEXT:
+					default:
+						props[field.name] = Property.ShortText({ displayName: field.name, required: false });
+						break;
+				}
+			}
+			return props;
+		},
+	}),
+};
+
+// Re-export for convenience
+export { TeableFieldType, TeableComputedFieldTypes };

