+import { AuthenticationType, HttpMethod, httpClient } from '@activepieces/pieces-common';
+import {
+  AppConnectionValueForAuthProperty,
+  PieceAuth,
+  Property,
+} from '@activepieces/pieces-framework';
+
+export const vercelAuth = PieceAuth.CustomAuth({
+  description:
+    'Authenticate with a Vercel personal access token. Optionally provide a team ID or team slug to operate on team-owned resources.',
+  required: true,
+  props: {
+    token: PieceAuth.SecretText({
+      displayName: 'Vercel Access Token',
+      description: 'Create a token in Vercel Settings → Tokens.',
+      required: true,
+    }),
+    teamId: Property.ShortText({
+      displayName: 'Team ID',
+      description: 'Optional. Use this to target a specific Vercel team.',
+      required: false,
+    }),
+    slug: Property.ShortText({
+      displayName: 'Team Slug',
+      description: 'Optional. Team slug. Ignored when Team ID is provided.',
+      required: false,
+    }),
+  },
+  validate: async ({ auth }) => {
+    try {
+      const queryParams: Record<string, string> = {
+        limit: '1',
+      };
+
+      if (auth.teamId) {
+        queryParams['teamId'] = auth.teamId;
+      } else if (auth.slug) {
+        queryParams['slug'] = auth.slug;
+      }
+
+      await httpClient.sendRequest({
+        method: HttpMethod.GET,
+        url: 'https://api.vercel.com/v10/projects',
+        authentication: {
+          type: AuthenticationType.BEARER_TOKEN,
+          token: auth.token,
+        },
+        queryParams,
+      });
+
+      return {
+        valid: true,
+      };
+    } catch (e) {
+      return {
+        valid: false,
+        error: (e as Error).message,
+      };
+    }
+  },
+});
+
+export type VercelAuthValue = AppConnectionValueForAuthProperty<typeof vercelAuth>;

diff --git a/packages/pieces/community/vercel/src/lib/common/client.ts b/packages/pieces/community/vercel/src/lib/common/client.ts
new file mode 100644
index 0000000000000000000000000000000000000000..9bb7e3b4de0963b85cc2437d4b8ecfc6f5c3c3fd
--- /dev/null
+++ b/packages/pieces/community/vercel/src/lib/common/client.ts
@@ -0,0 +1,157 @@
+import {
+  AuthenticationType,
+  httpClient,
+  HttpMethod,
+  HttpRequest,
+  QueryParams,
+} from '@activepieces/pieces-common';
+import { VercelAuthValue } from './auth';
+
+const BASE_URL = 'https://api.vercel.com';
+
+export type VercelApiCallParams = {
+  method: HttpMethod;
+  path: `/${string}`;
+  auth: VercelAuthValue;
+  query?: Record<string, string | number | boolean | undefined>;
+  body?: unknown;
+};
+
+export async function vercelApiCall<TResponse>({
+  method,
+  path,
+  auth,
+  query,
+  body,
+}: VercelApiCallParams): Promise<TResponse> {
+  const queryParams: QueryParams = {};
+
+  if (query) {
+    for (const [key, value] of Object.entries(query)) {
+      if (value !== undefined && value !== null && value !== '') {
+        queryParams[key] = String(value);
+      }
+    }
+  }
+
+  if (auth.props.teamId) {
+    queryParams['teamId'] = auth.props.teamId;
+  } else if (auth.props.slug) {
+    queryParams['slug'] = auth.props.slug;
+  }
+
+  const request: HttpRequest = {
+    method,
+    url: `${BASE_URL}${path}`,
+    authentication: {
+      type: AuthenticationType.BEARER_TOKEN,
+      token: auth.props.token,
+    },
+    headers: {
+      'Content-Type': 'application/json',
+    },
+    queryParams: Object.keys(queryParams).length > 0 ? queryParams : undefined,
+    body,
+  };
+
+  const response = await httpClient.sendRequest<TResponse>(request);
+  return response.body;
+}
+
+export type VercelProject = {
+  id: string;
+  name: string;
+  framework?: string | null;
+  accountId?: string;
+  latestDeployments?: Array<{
+    id?: string;
+    url?: string;
+    readyState?: string;
+    state?: string;
+    target?: string;
+  }>;
+  link?: {
+    repo?: string;
+    org?: string;
+    repoId?: string | number;
+    type?: string;
+  } | null;
+  updatedAt?: number;
+  createdAt?: number;
+};
+
+export async function listAllProjects(auth: VercelAuthValue, search?: string): Promise<VercelProject[]> {
+  const projects: VercelProject[] = [];
+  let nextFrom: string | undefined = undefined;
+  const MAX_PAGES = 10;
+  let pageCount = 0;
+
+  while (pageCount < MAX_PAGES) {
+    pageCount += 1;
+    const response: {
+      projects?: VercelProject[];
+      pagination?: {
+        next?: number | string | null;
+        count?: number;
+        prev?: number | string | null;
+      };
+    } | VercelProject[] = await vercelApiCall({
+      method: HttpMethod.GET,
+      path: '/v10/projects',
+      auth,
+      query: {
+        limit: 100,
+        from: nextFrom,
+        search,
+      },
+    });
+
+    const batch = Array.isArray(response) ? response : (response.projects ?? []);
+    projects.push(...batch);
+
+    const next: number | string | null | undefined = Array.isArray(response)
+      ? undefined
+      : response.pagination?.next;
+    if (!next) {
+      break;
+    }
+    nextFrom = String(next);
+  }
+
+  return projects;
+}
+
+export function toProjectDropdownOptions(projects: VercelProject[]) {
+  return projects.map((project) => ({
+    label: project.name,
+    value: project.id,
+  }));
+}
+
+export type VercelDeployment = {
+  uid: string;
+  name: string;
+  url: string | null;
+  state?: string;
+  target?: string | null;
+  created: number;
+};
+
+export async function listDeployments(
+  auth: VercelAuthValue,
+  projectId: string,
+): Promise<VercelDeployment[]> {
+  const response = await vercelApiCall<{
+    deployments: VercelDeployment[];
+    pagination: { next?: number | null };
+  }>({
+    method: HttpMethod.GET,
+    path: '/v6/deployments',
+    auth,
+    query: {
+      projectId,
+      limit: 100,
+    },
+  });
+  return response.deployments ?? [];
+}

