+const textAction = (
+  id: AIActionId,
+  promptName: PromptKey
+): AIActionDefinition => ({
+  id,
+  promptName,
+  responseType: 'text',
+  buildContent: options => options.input,
+});
+
+export const actionDefinitions = {
+  chat: {
+    id: 'chat',
+    promptName: 'Chat With AFFiNE AI',
+    responseType: 'text',
+    timeout: 5 * 60 * 1000,
