+          contextId,
+          fileId: item.fileId,
+        });
+      case 'tag':
+        return this.options.request.context.removeContextTag({
+          contextId,
+          tagId: item.tagId,
+        });
+      case 'collection':
+        return this.options.request.context.removeContextCollection({
+          contextId,
+          collectionId: item.collectionId,
+        });
+      case 'blob':
+        return this.options.request.context.removeContextBlob({
+          contextId,
+          blobId: item.blobId,
+        });
+    }
+  }
