+import type { AIToolsConfig } from '@affine/core/modules/ai-button';
+import type { CopilotChatHistoryFragment } from '@affine/graphql';
+
+export type AIChatScope =
+  | {
+      kind: 'doc';
+      workspaceId: string;
+      docId: string;
+      pendingSessionId?: string;
+    }
+  | {
+      kind: 'workspace';
+      workspaceId: string;
+    }
+  | {
+      kind: 'fork';
+      workspaceId: string;
+      parentSessionId: string;
+      latestMessageId?: string;
+      docId?: string;
+    }
+  | {
+      kind: 'chat-block';
+      workspaceId: string;
+      docId: string;
+      blockId: string;
+      parentSessionId?: string;
+      latestMessageId?: string;
+    }
+  | {
+      kind: 'playground';
+      workspaceId: string;
+      docId?: string;
+      parentSessionId?: string;
+      latestMessageId?: string;
+    };
+
+export type AIChatMessage = {
+  id: string;
+  role: 'user' | 'assistant';
+  content: string;
+  createdAt: string;
+  streamObjects?: unknown[];
