+      scope: AIChatScope;
+      hasMessages: false;
+    }
+  | {
+      kind: 'session';
+      id: string;
+      sessionId: string;
+      title: string;
+      docId: string | null;
+      pinned: boolean;
+      hasMessages: boolean;
+    };
+
+export type AIChatStatus =
+  | 'idle'
+  | 'loading'
+  | 'transmitting'
+  | 'success'
+  | 'error';
+
+export type AIChatHistoryGroups = {
+  currentDoc: CopilotChatHistoryFragment[];
+  recent: CopilotChatHistoryFragment[];
+  loading: boolean;
+  error: Error | null;
+};
+
+export type AIChatContextItem =
+  | {
+      kind: 'doc';
+      docId: string;
+      state?: string;
+      createdAt?: number;
+      tooltip?: string;
+    }
+  | {
+      kind: 'file';
+      file: File;
+      blobId?: string;
+      fileId?: string;
+      state?: string;
+      createdAt?: number;
+      tooltip?: string;
+    }
+  | {
+      kind: 'tag';
+      tagId: string;
+      docIds: string[];
+      state?: string;
+      createdAt?: number;
+      tooltip?: string;
+    }
+  | {
+      kind: 'collection';
+      collectionId: string;
+      docIds: string[];
+      state?: string;
+      createdAt?: number;
+      tooltip?: string;
+    }
+  | {
+      kind: 'blob';
+      blobId: string;
+      state?: string;
+      createdAt?: number;
+      tooltip?: string;
+    };
+
+export type AIChatContextState = {
+  contextId: string | null;
+  items: AIChatContextItem[];
+  loading: boolean;
+  polling: boolean;
+  error: Error | null;
+  embeddingCompleted: boolean;
+  embeddingCount: Record<'finished' | 'processing' | 'failed', number>;
+};
+
+export type AIChatComposerState = {
+  text: string;
+  attachments: (string | Blob | File)[];
+  context: AIChatContextState;
+  reasoning: boolean;
+  toolsConfig?: AIToolsConfig;
+  modelId?: string;
+};
+
+export type AIChatNavigationRequest = {
+  workspaceId: string;
+  docId: string;
+  sessionId: string;
+  resetTabs: true;
+};
+
+export type AIChatSnapshot = {
+  scope: AIChatScope;
+  readiness: 'initializing' | 'ready' | 'unavailable';
+  activeSessionId: string | null;
+  activeTabId: string | null;
+  tabs: AIChatTab[];
+  sessions: CopilotChatHistoryFragment[];
+  history: AIChatHistoryGroups;
+  messages: AIChatMessage[];
+  status: AIChatStatus;
+  error: Error | null;
+  composer: AIChatComposerState;
+  navigationRequest: AIChatNavigationRequest | null;
+  uiPolicy: {
+    showDraftTab: boolean;
+    canCreateNewSession: boolean;
+    canCloseActiveTab: boolean;
+    canPinActiveSession: boolean;
+    canSend: boolean;
+  };
+};
+
+export function createInitialComposerState(): AIChatComposerState {
+  return {
+    text: '',
+    attachments: [],
+    context: {
+      contextId: null,
+      items: [],
+      loading: false,
+      polling: false,
+      error: null,
+      embeddingCompleted: false,
+      embeddingCount: {
+        finished: 0,
+        processing: 0,
+        failed: 0,
+      },
+    },
+    reasoning: false,
+  };
+}
+
+export function sessionToTab(session: CopilotChatHistoryFragment): AIChatTab {
+  return {
+    kind: 'session',
+    id: session.sessionId,
+    sessionId: session.sessionId,
+    title: session.title || 'New chat',
+    docId: session.docId ?? null,
+    pinned: !!session.pinned,
+    hasMessages: !!session.messages?.length,
+  };
+}
+
+export function createDraftTab(scope: AIChatScope): AIChatTab {
+  return {
+    kind: 'draft',
+    id: `draft:${scope.kind}:${'docId' in scope ? (scope.docId ?? '') : ''}`,
+    title: 'New chat',
+    scope,
+    hasMessages: false,
+  };
+}

