+    const deploymentType =
+      env.selfhosted &&
+      entitlement.source === 'selfhost_license' &&
+      !entitlement.signedPayload
+        ? 'cloud'
+        : env.selfhosted
+          ? 'selfhosted'
+          : 'cloud';
