+
+  private assertAdminGrantInput(targetType: string, plan: string) {
+    const plans =
+      targetType === 'user'
+        ? ['pro', 'lifetime_pro', 'ai']
+        : targetType === 'workspace'
+          ? ['team']
+          : null;
+    if (!plans?.includes(plan)) {
