+    }
+
+    return await this.db.$executeRaw`
+      UPDATE workspace_invitations
+      SET
+        state = ${input.status},
+        inviter_id = ${input.inviterId ?? null},
+        updated_at = now()
+      WHERE workspace_id = ${input.workspaceId}
+        AND invitee_user_id = ${input.userId}
