+  private publishInviteLink(workspaceId: string, reason: string) {
+    this.publisher?.publishChanged(
+      'workspace.invite-link.changed',
+      { workspaceId },
+      reason,
+      { room: realtimeWorkspaceInviteLinkRoom(workspaceId) }
+    );
+  }
+}

