diff --git a/packages/lib/hooks/useElementByClassName.ts b/packages/lib/hooks/useElementByClassName.ts
new file mode 100644
index 0000000000000000000000000000000000000000..e3fa6f785bd19664117d2681baa166bcaa20e683
--- /dev/null
+++ b/packages/lib/hooks/useElementByClassName.ts
@@ -0,0 +1,18 @@
+import { useEffect, useRef } from "react";
+
+export function useElementByClassName<T extends HTMLElement = HTMLDivElement>(
+  className?: string
+): React.RefObject<T> {
+  const elementRef = useRef<T | null>(null);
+
+  useEffect(() => {
+    if (className) {
+      const element = document.getElementsByClassName(className)[0] as T;
+      elementRef.current = element || null;
+    } else {
+      elementRef.current = null;
+    }
+  }, [className]);
+
+  return elementRef;
+}

