--- /dev/null
+++ b/packages/lib/server-only/team/get-user-team-groups.ts
@@ -0,0 +1,46 @@
+import type { TeamGroup } from '@prisma/client';
+
+import { prisma } from '@documenso/prisma';
+
+export type GetUserTeamIdsOptions = {
+  userId: number;
+};
+
+/**
+ * Pre-resolve all team groups a user has access to via their organisation group memberships,
+ * keyed by team ID.
+ *
+ * This is significantly cheaper than joining team groups inline in a Prisma `findMany`
+ * because it avoids deep EXISTS subqueries and redundant LEFT JOINs per row.
+ */
+export const getUserTeamGroups = async ({
+  userId,
+}: GetUserTeamIdsOptions): Promise<Map<number, TeamGroup[]>> => {
+  const teamGroups = await prisma.teamGroup.findMany({
+    where: {
+      organisationGroup: {
+        organisationGroupMembers: {
+          some: {
+            organisationMember: {
+              userId,
+            },
+          },
+        },
+      },
+    },
+  });
+
+  const map = new Map<number, TeamGroup[]>();
+
+  for (const tg of teamGroups) {
+    const existing = map.get(tg.teamId);
+
+    if (existing) {
+      existing.push(tg);
+    } else {
+      map.set(tg.teamId, [tg]);
+    }
+  }
+
+  return map;
+};

diff --git a/packages/lib/server-only/template/search-templates-with-keyword.ts b/packages/lib/server-only/template/search-templates-with-keyword.ts
new file mode 100644
index 0000000000000000000000000000000000000000..3ac595c4ad4cd1bba390cdc0f0ab9299a33e1f80
--- /dev/null
+++ b/packages/lib/server-only/template/search-templates-with-keyword.ts
@@ -0,0 +1,135 @@
+import type { Prisma } from '@prisma/client';
+import { DocumentVisibility, EnvelopeType, TeamMemberRole } from '@prisma/client';
+import { match } from 'ts-pattern';
+
+import { formatTemplatesPath, getHighestTeamRoleInGroup } from '@documenso/lib/utils/teams';
+import { prisma } from '@documenso/prisma';
+
+import { mapSecondaryIdToTemplateId } from '../../utils/envelope';
+import { getUserTeamGroups } from '../team/get-user-team-groups';
+
+export type SearchTemplatesWithKeywordOptions = {
+  query: string;
+  userId: number;
+  limit?: number;
+};
+
+export const searchTemplatesWithKeyword = async ({
+  query,
+  userId,
+  limit = 20,
+}: SearchTemplatesWithKeywordOptions) => {
+  if (!query.trim()) {
+    return [];
+  }
+
+  const [user, teamGroupsByTeamId] = await Promise.all([
+    prisma.user.findFirstOrThrow({
+      where: {
+        id: userId,
+      },
+    }),
+    getUserTeamGroups({ userId }),
+  ]);
+
+  const teamIds = [...teamGroupsByTeamId.keys()];
+
+  const filters: Prisma.EnvelopeWhereInput[] = [
+    // Templates owned by the user matching title or recipient email.
+    {
+      userId,
+      deletedAt: null,
+      OR: [
+        { title: { contains: query, mode: 'insensitive' } },
+        {
+          recipients: {
+            some: { email: { contains: query, mode: 'insensitive' } },
+          },
+        },
+      ],
+    },
+  ];
+
+  // Team templates the user has access to.
+  if (teamIds.length > 0) {
+    filters.push({
+      teamId: { in: teamIds },
+      deletedAt: null,
+      OR: [
+        { title: { contains: query, mode: 'insensitive' } },
+        {
+          recipients: {
+            some: { email: { contains: query, mode: 'insensitive' } },
+          },
+        },
+      ],
+    });
+  }
+
+  const envelopes = await prisma.envelope.findMany({
+    where: {
+      type: EnvelopeType.TEMPLATE,
+      OR: filters,
+    },
+    select: {
+      id: true,
+      userId: true,
+      teamId: true,
+      title: true,
+      secondaryId: true,
+      visibility: true,
+      recipients: {
+        select: {
+          email: true,
+        },
+      },
+      team: {
+        select: {
+          url: true,
+        },
+      },
+    },
+    distinct: ['id'],
+    orderBy: {
+      createdAt: 'desc',
+    },
+    // Over-fetch to compensate for post-query visibility filtering on team templates.
+    take: limit * 3,
+  });
+
+  const results = envelopes
+    .filter((envelope) => {
+      if (!envelope.teamId || envelope.userId === user.id) {
+        return true;
+      }
+
+      const teamGroups = teamGroupsByTeamId.get(envelope.teamId) ?? [];
+      const teamMemberRole = getHighestTeamRoleInGroup(teamGroups);
+
+      if (!teamMemberRole) {
+        return false;
+      }
+
+      return match([envelope.visibility, teamMemberRole])
+        .with([DocumentVisibility.EVERYONE, TeamMemberRole.ADMIN], () => true)
+        .with([DocumentVisibility.EVERYONE, TeamMemberRole.MANAGER], () => true)
+        .with([DocumentVisibility.EVERYONE, TeamMemberRole.MEMBER], () => true)
+        .with([DocumentVisibility.MANAGER_AND_ABOVE, TeamMemberRole.ADMIN], () => true)
+        .with([DocumentVisibility.MANAGER_AND_ABOVE, TeamMemberRole.MANAGER], () => true)
+        .with([DocumentVisibility.ADMIN, TeamMemberRole.ADMIN], () => true)
+        .otherwise(() => false);
+    })
+    .slice(0, limit)
+    .map((envelope) => {
+      const legacyTemplateId = mapSecondaryIdToTemplateId(envelope.secondaryId);
+      const path = `${formatTemplatesPath(envelope.team.url)}/${legacyTemplateId}`;
+
+      return {
+        title: envelope.title,
+        path,
+        value: [envelope.id, envelope.title, ...envelope.recipients.map((r) => r.email)].join(' '),
+      };
+    });
+
+  return results;
+};

diff --git a/packages/prisma/seed/medium-account-seed.ts b/packages/prisma/seed/medium-account-seed.ts
new file mode 100644
index 0000000000000000000000000000000000000000..f10df2ee0d4db7f54cfde3e8f5f806f50049fed9
--- /dev/null
+++ b/packages/prisma/seed/medium-account-seed.ts
@@ -0,0 +1,77 @@
+import { nanoid } from 'nanoid';
+
+import { prisma } from '..';
+import { DocumentStatus } from '../client';
+import { seedBlankDocument } from './documents';
+import { seedUser } from './users';
+
+const MEDIUM_ACCOUNT_EMAIL = 'medium-account@documenso.com';
+const DOCUMENT_COUNT = 1000;
+
+const STATUSES = [DocumentStatus.DRAFT, DocumentStatus.PENDING, DocumentStatus.COMPLETED];
+
+export const seedDatabase = async () => {
+  const existingUser = await prisma.user.findFirst({
+    where: {
+      email: MEDIUM_ACCOUNT_EMAIL,
+    },
+  });
+
+  if (existingUser) {
+    return;
+  }
+
+  console.log(`[SEEDING]: Creating medium account with ${DOCUMENT_COUNT} documents...`);
+
+  const { user, team } = await seedUser({
+    name: 'Medium Account',
+    email: MEDIUM_ACCOUNT_EMAIL,
+  });
+
+  const recipientEmails = Array.from({ length: 20 }, (_, i) => `recipient-${i}@test.documenso.com`);
+
+  for (let i = 0; i < DOCUMENT_COUNT; i++) {
+    const status = STATUSES[i % STATUSES.length];
+
+    const document = await seedBlankDocument(user, team.id, {
+      key: `medium-${i}`,
+      createDocumentOptions: {
+        title: `[MEDIUM] Document ${i} - ${status}`,
+        status,
+      },
+    });
+
+    // Add 1-3 recipients per document.
+    const recipientCount = (i % 3) + 1;
+
+    for (let r = 0; r < recipientCount; r++) {
+      await prisma.recipient.create({
+        data: {
+          email: recipientEmails[(i + r) % recipientEmails.length],
+          name: `Recipient ${r}`,
+          token: nanoid(),
+          envelopeId: document.id,
+        },
+      });
+    }
+
+    // Also create some documents where the medium user is a recipient (not owner).
+    // Every 5th document, create an extra doc owned by a "ghost" sender with medium user as recipient.
+    if (i % 5 === 0) {
+      await prisma.recipient.create({
+        data: {
+          email: MEDIUM_ACCOUNT_EMAIL,
+          name: 'Medium Account',
+          token: nanoid(),
+          envelopeId: document.id,
+        },
+      });
+    }
+
+    if (i % 100 === 0) {
+      console.log(`[SEEDING]: Created ${i}/${DOCUMENT_COUNT} documents...`);
+    }
+  }
+
+  console.log(`[SEEDING]: Medium account seeded with ${DOCUMENT_COUNT} documents.`);
+};

