+        }
+
+        const result = await updateContactAttributes(parsedInput.contactId, parsedInput.attributes);
+
+        ctx.auditLoggingCtx.newObject = {
+          contactId: parsedInput.contactId,
+          attributes: result.updatedAttributes,
+        };
+
+        return result;
+      }
+    )
+  );

