diff --git a/apps/api/src/middleware/api-key.ts b/apps/api/src/middleware/api-key.ts
new file mode 100644
index 0000000000000000000000000000000000000000..587828dddeee21a1e5526041efe86842e684348b
--- /dev/null
+++ b/apps/api/src/middleware/api-key.ts
@@ -0,0 +1,84 @@
+import crypto from "node:crypto";
+import {
+  extractApiKeyPrefix,
+  verifyApiKey,
+} from "@rallly/api-core/auth/api-key";
+import { prisma } from "@rallly/database";
+import { createLogger } from "@rallly/logger";
+import { bearerAuth } from "hono/bearer-auth";
+
+const logger = createLogger("api/middleware/api-key");
+
+export const spaceApiKeyAuth = bearerAuth({
+  verifyToken: async (rawKey, c) => {
+    const prefix = extractApiKeyPrefix(rawKey);
+    const prefixBuffer = Buffer.from(prefix);
+
+    // Query candidate keys to avoid timing attack via database lookup
+    // We use a partial prefix match to narrow the search space
+    const now = new Date();
+    const candidateKeys = await prisma.spaceApiKey.findMany({
+      where: {
+        prefix: {
+          startsWith: prefix.slice(0, Math.min(4, prefix.length)),
+        },
+        revokedAt: null,
+        OR: [{ expiresAt: null }, { expiresAt: { gt: now } }],
+      },
+      select: {
+        id: true,
+        prefix: true,
+        spaceId: true,
+        hashedKey: true,
+        expiresAt: true,
+        revokedAt: true,
+        space: {
+          select: {
+            ownerId: true,
+          },
+        },
+      },
+    });
+
+    let apiKeyId: string | null = null;
+    let spaceId: string | null = null;
+    let spaceOwnerId: string | null = null;
+    for (const candidate of candidateKeys) {
+      // Timing-safe prefix comparison
+      const candidateBuffer = Buffer.from(candidate.prefix);
+      if (
+        prefixBuffer.length === candidateBuffer.length &&
+        crypto.timingSafeEqual(prefixBuffer, candidateBuffer)
+      ) {
+        // Verify the full key hash
+        const isValid = await verifyApiKey(rawKey, candidate.hashedKey);
+        if (isValid) {
+          apiKeyId = candidate.id;
+          spaceId = candidate.spaceId;
+          spaceOwnerId = candidate.space.ownerId;
+        }
+      }
+    }
+
+    if (!apiKeyId || !spaceId || !spaceOwnerId) {
+      return false;
+    }
+
+    c.set("apiAuth", {
+      spaceId,
+      spaceOwnerId,
+      apiKeyId,
+    });
+
+    prisma.spaceApiKey
+      .update({
+        where: { id: apiKeyId },
+        data: { lastUsedAt: new Date() },
+      })
+      .catch((error) => {
+        logger.error({ error, apiKeyId }, "failed to update lastUsedAt");
+      });
+
+    return true;
+  },
+});

diff --git a/apps/api/src/routes/polls.ts b/apps/api/src/routes/polls.ts
