new file mode 100644
index 0000000000000000000000000000000000000000..c61726c10cf538ee116e0669bf7db41c3dc1c7a6
--- /dev/null
+++ b/apps/api/src/utils/time-slots.ts
@@ -0,0 +1,126 @@
+import dayjs from "dayjs";
+import isSameOrBefore from "dayjs/plugin/isSameOrBefore";
+import timezone from "dayjs/plugin/timezone";
+import utc from "dayjs/plugin/utc";
+
+dayjs.extend(utc);
+dayjs.extend(timezone);
+dayjs.extend(isSameOrBefore);
+
+export type SlotGeneratorInput = {
+  startDate: string;
+  endDate: string;
+  daysOfWeek: Array<"mon" | "tue" | "wed" | "thu" | "fri" | "sat" | "sun">;
+  fromTime: string;
+  toTime: string;
+  interval?: number;
+};
+
+export type TimeSlot = {
+  startTime: Date;
+  duration: number;
+};
+
+export const dedupeTimeSlots = (slots: Array<TimeSlot>) => {
+  const unique = new Map<string, TimeSlot>();
+  for (const slot of slots) {
+    unique.set(`${slot.startTime.getTime()}:${slot.duration}`, slot);
+  }
+  return Array.from(unique.values());
+};
+
+const hasTzOffset = (value: string) =>
+  /[zZ]$|[+-]\d{2}:\d{2}$|[+-]\d{4}$/.test(value);
+
+const parseDateTimeInTimeZone = (value: string, timeZone?: string) =>
+  hasTzOffset(value)
+    ? dayjs(value)
+    : timeZone
+      ? dayjs(value).tz(timeZone, true)
+      : dayjs(value).utc(true);
+
+const parseLocalDateTimeInTimeZone = (
+  date: string,
+  time: string,
+  timeZone: string | undefined,
+) =>
+  timeZone
+    ? dayjs(`${date}T${time}`).tz(timeZone, true)
+    : dayjs(`${date}T${time}`).utc(true);
+
+export const parseStartTime = (
+  startTime: string,
+  timeZone: string | undefined,
+  duration: number,
+): TimeSlot => ({
+  startTime: parseDateTimeInTimeZone(startTime, timeZone).toDate(),
+  duration,
+});
+
+export const generateTimeSlots = (
+  generator: SlotGeneratorInput,
+  timeZone: string | undefined,
+  durationMinutes: number,
+): Array<TimeSlot> => {
+  const dayMap: Record<SlotGeneratorInput["daysOfWeek"][number], number> = {
+    sun: 0,
+    mon: 1,
+    tue: 2,
+    wed: 3,
+    thu: 4,
+    fri: 5,
+    sat: 6,
+  };
+
+  const allowed = new Set(generator.daysOfWeek.map((d) => dayMap[d]));
+
+  // Use UTC for date iteration to avoid local timezone interference
+  const startDay = dayjs.utc(generator.startDate).startOf("day");
+  const endDay = dayjs.utc(generator.endDate).startOf("day");
+
+  const results: Array<TimeSlot> = [];
+
+  for (
+    let cursor = startDay;
+    cursor.isSameOrBefore(endDay, "day");
+    cursor = cursor.add(1, "day")
+  ) {
+    const date = cursor.format("YYYY-MM-DD");
+    // Get day of week in the target timezone
+    const dayInTz = timeZone ? dayjs.tz(date, timeZone).day() : cursor.day();
+    if (!allowed.has(dayInTz)) {
+      continue;
+    }
+    const windowStart = parseLocalDateTimeInTimeZone(
+      date,
+      generator.fromTime,
+      timeZone,
+    );
+    const windowEnd = parseLocalDateTimeInTimeZone(
+      date,
+      generator.toTime,
+      timeZone,
+    );
+    if (!windowEnd.isAfter(windowStart)) {
+      continue;
+    }
+
+    const duration = durationMinutes;
+    const interval = generator.interval ?? durationMinutes;
+    const totalMinutes = windowEnd.diff(windowStart, "minute");
+
+    for (
+      let offset = 0;
+      offset + duration <= totalMinutes;
+      offset += interval
+    ) {
+      const t = windowStart.add(offset, "minute");
+      results.push({
+        startTime: t.toDate(),
+        duration,
+      });
+    }
+  }
+
+  return results;
+};

diff --git a/apps/api/src/utils/timezone-schema.ts b/apps/api/src/utils/timezone-schema.ts
new file mode 100644
index 0000000000000000000000000000000000000000..fdc0d114202fc9f07a972feda77edb182230777f
--- /dev/null
+++ b/apps/api/src/utils/timezone-schema.ts
@@ -0,0 +1,56 @@
+import { z } from "zod";
+
+// Override runtime canonicalization when ICU data lags behind IANA updates.
+const ianaOverrides: Record<string, string> = {
+  "Europe/Kiev": "Europe/Kyiv",
+};
+
+export function normalizeLegacyIanaId(id: string): string {
+  return ianaOverrides[id] ?? id;
+}
+
+const fixedOffsetPrefixes = ["etc/", "gmt", "utc"];
+
+function isGeographic(timeZone: string) {
+  const lower = timeZone.toLowerCase();
+  return !fixedOffsetPrefixes.some((prefix) => lower.startsWith(prefix));
+}
+
+/**
+ * Resolve timezone to its canonical IANA ID via the runtime,
+ * then apply manual overrides for cases where the runtime is outdated.
+ * Returns the canonical ID or null if the timezone is invalid.
+ */
+function resolveTimezone(tz: string): string | null {
+  try {
+    const resolved = Intl.DateTimeFormat(undefined, {
+      timeZone: tz,
+    }).resolvedOptions().timeZone;
+    return normalizeLegacyIanaId(resolved);
+  } catch {
+    return null;
+  }
+}
+
+export const timezoneSchema = z.string().transform((tz, ctx) => {
+  const resolved = resolveTimezone(tz);
+  if (resolved === null) {
+    ctx.issues.push({
+      code: "custom",
+      message: "Must be a valid IANA timezone",
+      input: tz,
+    });
+    return z.NEVER;
+  }
+
+  if (!isGeographic(resolved)) {
+    ctx.issues.push({
+      code: "custom",
+      message: "Must be a geographic timezone",
+      input: tz,
+    });
+    return z.NEVER;
+  }
+
+  return resolved;
+});

