@@ -0,0 +1,41 @@
+import { RQAPI } from "features/apiClient/types";
+import { collection, doc, getFirestore, setDoc, Timestamp } from "firebase/firestore";
+import firebaseApp from "../../firebase";
+import { APIS_NODE, EXAMPLES_REQUESTS_NODE } from "./constants";
+import { getOwnerId } from "backend/utils";
+import * as Sentry from "@sentry/react";
+import { sanitizeExample } from "./utils";
+
+export const createExample = async (
+  uid: string,
+  parentRequestId: string,
+  example: RQAPI.ExampleApiRecord,
+  teamId?: string
+): RQAPI.ApiClientRecordPromise => {
+  try {
+    const db = getFirestore(firebaseApp);
+    const examplesRef = collection(db, APIS_NODE, parentRequestId, EXAMPLES_REQUESTS_NODE);
+    const ownerId = getOwnerId(uid, teamId);
+
+    const sanitizedExample = sanitizeExample(example);
+    delete sanitizedExample?.id;
+
+    const newExampleRecord: Partial<RQAPI.ExampleApiRecord> = {
+      ...sanitizedExample,
+      ownerId,
+      deleted: false,
+      createdBy: uid,
+      updatedBy: uid,
+      createdTs: Timestamp.now().toMillis(),
+      updatedTs: Timestamp.now().toMillis(),
+    };
+    const docRef = doc(examplesRef);
+    const createdRecord = { ...newExampleRecord, id: docRef.id } as RQAPI.ExampleApiRecord;
+    await setDoc(docRef, createdRecord);
+
+    return { success: true, data: createdRecord };
+  } catch (error) {
+    Sentry.captureException(error);
+    return { success: false, data: null, message: "Failed to create example request" };
+  }
+};

diff --git a/app/src/backend/apiClient/deleteExamples.ts b/app/src/backend/apiClient/deleteExamples.ts
new file mode 100644
index 0000000000000000000000000000000000000000..9193bf040924d50c0efc884505a3212b8991e2b8
--- /dev/null
+++ b/app/src/backend/apiClient/deleteExamples.ts
@@ -0,0 +1,28 @@
+import { doc, getFirestore, Timestamp, writeBatch } from "firebase/firestore";
+import firebaseApp from "../../firebase";
+import { APIS_NODE, EXAMPLES_REQUESTS_NODE } from "./constants";
+import { RQAPI } from "features/apiClient/types";
+import * as Sentry from "@sentry/react";
+
+export const deleteExamples = async (uid: string, exampleRecords: RQAPI.ExampleApiRecord[]) => {
+  try {
+    const db = getFirestore(firebaseApp);
+    const exampleRefs = exampleRecords.map((example) =>
+      doc(db, APIS_NODE, example.parentRequestId, EXAMPLES_REQUESTS_NODE, example.id)
+    );
+    const batch = writeBatch(db);
+    exampleRefs.forEach((exampleRef) => {
+      batch.update(exampleRef, {
+        deleted: true,
+        updatedBy: uid,
+        updatedTs: Timestamp.now().toMillis(),
+      });
+    });
+    await batch.commit();
+
+    return { success: true };
+  } catch (error) {
+    Sentry.captureException(error);
+    return { success: false };
+  }
+};

diff --git a/app/src/backend/apiClient/getAllExamples.ts b/app/src/backend/apiClient/getAllExamples.ts
new file mode 100644
index 0000000000000000000000000000000000000000..2e25fe8620f606ca29fa8c1764c4def25610ade5
--- /dev/null
+++ b/app/src/backend/apiClient/getAllExamples.ts
@@ -0,0 +1,73 @@
+import firebaseApp from "../../firebase";
+import { collection, getDocs, getFirestore, query, where } from "firebase/firestore";
+import { RQAPI } from "features/apiClient/types";
+import Logger from "lib/logger";
+import { enforceLatestRecordSchema } from "./parser";
+import { APIS_NODE, EXAMPLES_REQUESTS_NODE } from "./constants";
+
+const getApiRecordExamples = async (
+  ownerId: string,
+  parentRequestId: string
+): Promise<{ success: boolean; data: RQAPI.ExampleApiRecord[] }> => {
+  if (!parentRequestId) {
+    return { success: false, data: [] };
+  }
+
+  const db = getFirestore(firebaseApp);
+  const examplesRef = collection(db, APIS_NODE, parentRequestId, EXAMPLES_REQUESTS_NODE);
+
+  try {
+    const q = query(examplesRef, where("ownerId", "==", ownerId), where("deleted", "in", [false]));
+    const result: RQAPI.ExampleApiRecord[] = [];
+    const snapshot = await getDocs(q);
+
+    if (snapshot.empty) {
+      return { success: true, data: result };
+    }
+
+    snapshot.forEach((doc) => {
+      const data = doc.data();
+      const id = doc.id;
+      const processedData = enforceLatestRecordSchema(id, data) as RQAPI.ExampleApiRecord;
+      result.push(processedData);
+    });
+    return { success: true, data: result };
+  } catch (error) {
+    return { success: false, data: [] };
+  }
+};
+
+export const getExamplesForApiRecords = async (
+  ownerId: string,
+  apiRecordIds: string[]
+): Promise<{ success: boolean; data: RQAPI.ExampleApiRecord[]; failedRecordIds?: string[] }> => {
+  if (!apiRecordIds.length) {
+    return { success: true, data: [] };
+  }
+
+  try {
+    const examplePromises = apiRecordIds.map((recordId) => getApiRecordExamples(ownerId, recordId));
+    const results = await Promise.all(examplePromises);
+
+    const allExamples: RQAPI.ExampleApiRecord[] = [];
+    const failedRecordIds: string[] = [];
+    results.forEach((result, index) => {
+      if (result.success) {
+        allExamples.push(...result.data);
+      } else {
+        const recordId = apiRecordIds[index];
+        if (recordId) {
+          failedRecordIds.push(recordId);
+        }
+      }
+    });
+    return {
+      success: true,
+      data: allExamples,
+      failedRecordIds: failedRecordIds ?? [],
+    };
+  } catch (error) {
+    Logger.error("Error fetching examples for multiple API records:", error);
+    return { success: false, data: [] };
+  }
+};

