diff --git a/app/src/views/misc/ExtensionInstalledScreen/getExtensionInstallLink.ts b/app/src/views/misc/ExtensionInstalledScreen/getExtensionInstallLink.ts
new file mode 100644
index 0000000000000000000000000000000000000000..9ede01b4aa23648a73c4bc66114054d315567e9a
--- /dev/null
+++ b/app/src/views/misc/ExtensionInstalledScreen/getExtensionInstallLink.ts
@@ -0,0 +1,18 @@
+import { supportedBrowserExtensions } from "components/misc/InstallExtensionCTA/supportedBrowserExtensions";
+import UAParser from "ua-parser-js";
+
+export default function getExtensionInstallLink() {
+  const parser = new UAParser();
+  parser.setUA(window.navigator.userAgent);
+  const result = parser.getResult();
+  const browserDetected = result.browser.name;
+  let currentBrowserData = supportedBrowserExtensions[0]; // default chrome
+
+  for (let extensionData of supportedBrowserExtensions) {
+    if (extensionData.name === browserDetected) {
+      currentBrowserData = extensionData;
+    }
+  }
+
+  return currentBrowserData.downloadURL;
+}

diff --git a/app/src/views/misc/ExtensionInstalledScreen/index.tsx b/app/src/views/misc/ExtensionInstalledScreen/index.tsx
