diff --git a/app/src/features/apiClient/errors/SoapImportError/SoapImportError.ts b/app/src/features/apiClient/errors/SoapImportError/SoapImportError.ts
new file mode 100644
index 0000000000000000000000000000000000000000..3850d126fa78accc9b1d9b4c594bf1a86c3571be
--- /dev/null
+++ b/app/src/features/apiClient/errors/SoapImportError/SoapImportError.ts
@@ -0,0 +1,53 @@
+import { NativeError } from "errors/NativeError";
+
+export enum WsdlFetchErrorType {
+  INVALID_URL = "INVALID_URL",
+  FETCH_FAILED = "FETCH_FAILED",
+  INVALID_RESPONSE = "INVALID_RESPONSE",
+  NETWORK_ERROR = "NETWORK_ERROR",
+  TIMEOUT = "TIMEOUT",
+}
+
+export const SOAP_IMPORT_ERROR_MESSAGES: Record<WsdlFetchErrorType, string> = {
+  [WsdlFetchErrorType.INVALID_URL]: "Please enter a valid WSDL URL",
+  [WsdlFetchErrorType.FETCH_FAILED]: "Failed to fetch WSDL from the provided URL",
+  [WsdlFetchErrorType.INVALID_RESPONSE]: "The response does not appear to be valid WSDL/XML",
+  [WsdlFetchErrorType.NETWORK_ERROR]: "Network error while fetching WSDL",
+  [WsdlFetchErrorType.TIMEOUT]: "Request timeout while fetching WSDL",
+};
+
+export class WsdlFetchError extends NativeError {
+  constructor(readonly errorType: WsdlFetchErrorType, customMessage?: string, readonly originalError?: unknown) {
+    const message = customMessage || SOAP_IMPORT_ERROR_MESSAGES[errorType];
+    super(message);
+    this.name = "WsdlFetchError";
+
+    if (originalError) {
+      this.cause = originalError;
+    }
+
+    if (Error.captureStackTrace) {
+      Error.captureStackTrace(this, this.constructor);
+    }
+  }
+
+  static invalidUrl(originalError?: unknown) {
+    return new WsdlFetchError(WsdlFetchErrorType.INVALID_URL, undefined, originalError);
+  }
+
+  static fetchFailed(customMessage?: string, originalError?: unknown) {
+    return new WsdlFetchError(WsdlFetchErrorType.FETCH_FAILED, customMessage, originalError);
+  }
+
+  static invalidResponse(originalError?: unknown) {
+    return new WsdlFetchError(WsdlFetchErrorType.INVALID_RESPONSE, undefined, originalError);
+  }
+
+  static networkError(customMessage?: string, originalError?: unknown) {
+    return new WsdlFetchError(WsdlFetchErrorType.NETWORK_ERROR, customMessage, originalError);
+  }
+
+  static timeout(originalError?: unknown) {
+    return new WsdlFetchError(WsdlFetchErrorType.TIMEOUT, undefined, originalError);
+  }
+}

diff --git a/app/src/features/apiClient/hooks/useWsdlFetcher.ts b/app/src/features/apiClient/hooks/useWsdlFetcher.ts
new file mode 100644
index 0000000000000000000000000000000000000000..ba8a416476ea3275de4e55534f42234e96aa9e16
--- /dev/null
+++ b/app/src/features/apiClient/hooks/useWsdlFetcher.ts
@@ -0,0 +1,97 @@
+import { useCallback, useState } from "react";
+import { v4 as uuidv4 } from "uuid";
+import { useHttpRequestExecutor } from "./requestExecutors/useHttpRequestExecutor";
+import { RQAPI } from "@requestly/shared/types/entities/apiClient";
+import { WsdlFetchError } from "../errors/SoapImportError/SoapImportError";
+import { ImportFile } from "../screens/apiClient/components/CommonApiClientImporter/CommonApiClientImporter";
+import { RequestMethod } from "../types";
+import { getDefaultAuth } from "../screens/apiClient/components/views/components/request/components/AuthorizationView/defaults";
+import { extractQueryParams } from "../screens/apiClient/utils";
+
+interface UseWsdlFetcherResult {
+  isFetching: boolean;
+  fetchWsdlFromUrl: (url: string) => Promise<ImportFile>;
+}
+
+export const useWsdlFetcher = (): UseWsdlFetcherResult => {
+  const [isFetching, setIsFetching] = useState(false);
+
+  // Create a temporary record ID for the executor
+  const [tempRecordId] = useState(() => uuidv4());
+  const httpRequestExecutor = useHttpRequestExecutor(tempRecordId);
+
+  const fetchWsdlFromUrl = useCallback(
+    async (url: string): Promise<ImportFile> => {
+      const urlValidationRegex = /^https?:\/\//i;
+      if (!urlValidationRegex.test(url)) {
+        throw WsdlFetchError.invalidUrl();
+      }
+
+      setIsFetching(true);
+
+      try {
+        // Create a GET request to fetch the WSDL
+        const queryParams = extractQueryParams(url);
+        const httpRequest: RQAPI.HttpRequest = {
+          url: url.trim(),
+          method: RequestMethod.GET,
+          headers: [],
+          queryParams: queryParams,
+          body: "",
+          contentType: undefined,
+        };
+
+        const entry: RQAPI.HttpApiEntry = {
+          type: RQAPI.ApiEntryType.HTTP,
+          request: httpRequest,
+          response: null,
+          scripts: { preRequest: "", postResponse: "" },
+          auth: getDefaultAuth(false),
+          testResults: undefined,
+        };
+
+        // Execute the request
+        const executionResult = await httpRequestExecutor.execute(
+          {
+            entry: entry,
+            recordId: tempRecordId,
+          },
+          {
+            iteration: 0,
+            iterationCount: 1,
+          }
+        );
+
+        if (executionResult.status === "error") {
+          throw WsdlFetchError.fetchFailed(executionResult.error?.message, executionResult.error);
+        }
+
+        const response = executionResult.executedEntry?.response;
+        if (!response || !response.body) {
+          throw WsdlFetchError.invalidResponse();
+        }
+
+        // Create ImportFile object from the fetched content
+        const importFile: ImportFile = {
+          content: response.body,
+          name: "Url Response",
+          type: "application/soap+xml",
+        };
+
+        return importFile;
+      } catch (err) {
+        // Re-throw WsdlFetchError as-is, wrap other errors
+        if (err instanceof WsdlFetchError) {
+          throw err;
+        }
+        const originalError = err instanceof Error ? err : new Error("Unknown error");
+        throw WsdlFetchError.fetchFailed(originalError.message, originalError);
+      } finally {
+        setIsFetching(false);
+      }
+    },
+    [httpRequestExecutor, tempRecordId]
+  );
+
+  return { isFetching, fetchWsdlFromUrl };
+};

