diff --git a/app/src/features/apiClient/slices/secrets-manager/selectors.ts b/app/src/features/apiClient/slices/secrets-manager/selectors.ts
new file mode 100644
index 0000000000000000000000000000000000000000..d172ffe727f3f496b022a9dccb450881d1d059db
--- /dev/null
+++ b/app/src/features/apiClient/slices/secrets-manager/selectors.ts
@@ -0,0 +1,92 @@
+import { createSelector } from "@reduxjs/toolkit";
+import { providersAdapter, secretsAdapter } from "./adapters";
+import { SecretsManagerState } from "./types";
+import { AwsSecretValue } from "@requestly/shared/types/entities/secretsManager";
+
+type RootState = { secretsManager: SecretsManagerState };
+
+const selectSecretsManagerSlice = (state: RootState) => state.secretsManager;
+
+const selectProvidersState = createSelector(selectSecretsManagerSlice, (slice) => slice.providers);
+const providersAdapterSelectors = providersAdapter.getSelectors(selectProvidersState);
+
+const selectSecretsState = createSelector(selectSecretsManagerSlice, (slice) => slice.secrets);
+const secretsAdapterSelectors = secretsAdapter.getSelectors(selectSecretsState);
+
+export const selectAllSecretProviders = providersAdapterSelectors.selectAll;
+export const selectSecretProviderById = (state: RootState, id: string) =>
+  providersAdapterSelectors.selectById(state, id);
+
+export const selectAllSecrets = secretsAdapterSelectors.selectAll;
+export const selectSecretById = (state: RootState, id: string) => secretsAdapterSelectors.selectById(state, id);
+
+export const selectSelectedProviderId = createSelector(selectSecretsManagerSlice, (slice) => slice.selectedProviderId);
+
+export const selectFetchStatus = createSelector(selectSecretsManagerSlice, (slice) => slice.fetchStatus);
+
+export const selectSecretsForSelectedProvider = createSelector(
+  [selectAllSecrets, selectSelectedProviderId],
+  (secrets, selectedProviderId) => {
+    if (!selectedProviderId) return [];
+    return secrets.filter((s) => s.providerId === selectedProviderId);
+  }
+);
+
+export const selectSecretsByProviderId = createSelector([selectAllSecrets], (secrets) => (providerId: string) => {
+  return secrets.filter((s) => s.providerId === providerId);
+});
+
+export const selectLastFetchedForSelectedProvider = createSelector([selectSecretsForSelectedProvider], (secrets) => {
+  const fetched = secrets.filter((s) => s.fetchedAt > 0);
+  if (fetched.length === 0) return null;
+  return Math.max(...fetched.map((s) => s.fetchedAt));
+});
+
+const selectSecretsSnapshot = createSelector(selectSecretsManagerSlice, (slice) => slice.secretsSnapshot);
+
+export const selectIsDirtyForSelectedProvider = createSelector(
+  [selectSecretsForSelectedProvider, selectSecretsSnapshot],
+  (secrets, snapshot) => {
+    // Filter out empty stub rows — they don't count as changes
+    const meaningfulSecrets = secrets.filter((s) => {
+      const ref = s.secretReference as AwsSecretValue["secretReference"];
+      const alias = (s.secretReference.alias ?? "").trim();
+      const identifier = (ref.identifier ?? "").trim();
+      return alias !== "" && identifier !== "";
+    });
+
+    const snapshotIds = new Set(Object.keys(snapshot));
+    const currentIds = new Set(meaningfulSecrets.map((s) => s.secretReference.id));
+
+    // Any new meaningful secret not in snapshot = dirty
+    for (const id of currentIds) {
+      if (!snapshotIds.has(id)) return true;
+    }
+
+    // Any snapshot entry not in current meaningful secrets = dirty (was deleted)
+    for (const id of snapshotIds) {
+      if (!currentIds.has(id)) return true;
+    }
+
+    // Compare fields for each matching ID
+    for (const secret of meaningfulSecrets) {
+      const snap = snapshot[secret.secretReference.id];
+      if (!snap) return true;
+
+      const ref = secret.secretReference as AwsSecretValue["secretReference"];
+      if (
+        ref.alias !== snap.alias ||
+        ref.identifier !== snap.identifier ||
+        String(ref.version ?? "") !== snap.version
+      ) {
+        return true;
+      }
+    }
+
+    return false;
+  }
+);
+
+export const selectFetchErrors = createSelector(selectSecretsManagerSlice, (slice) => slice.fetchErrors);
+
+export const selectValidationErrors = createSelector(selectSecretsManagerSlice, (slice) => slice.validationErrors);

diff --git a/app/src/features/apiClient/slices/secrets-manager/slice.ts b/app/src/features/apiClient/slices/secrets-manager/slice.ts
new file mode 100644
index 0000000000000000000000000000000000000000..ab672ad34db55339b68300c5b88f646acf007367
--- /dev/null
+++ b/app/src/features/apiClient/slices/secrets-manager/slice.ts
@@ -0,0 +1,180 @@
+import { createSlice, PayloadAction } from "@reduxjs/toolkit";
+import { SECRETS_MANAGER_SLICE_NAME } from "../common/constants";
+import {
+  SecretProviderMetadata,
+  SecretProviderType,
+  SecretValue,
+  AwsSecretValue,
+} from "@requestly/shared/types/entities/secretsManager";
+import { SecretSnapshot, SecretsManagerState } from "./types";
+import { fetchAndSaveSecretsForProvider, listSecrets } from "./thunks";
+import { providersAdapter, secretsAdapter } from "./adapters";
+import persistReducer from "redux-persist/es/persistReducer";
+import storage from "redux-persist/lib/storage";
+
+export { providersAdapter, secretsAdapter } from "./adapters";
+
+const initialState: SecretsManagerState = {
+  providers: providersAdapter.getInitialState(),
+  secrets: secretsAdapter.getInitialState(),
+  selectedProviderId: null,
+  fetchStatus: "idle",
+  fetchErrors: {},
+  validationErrors: {},
+  secretsSnapshot: {},
+};
+
+function removeSecretsForProvider(state: SecretsManagerState, providerId: string) {
+  const allSecrets = secretsAdapter.getSelectors().selectAll(state.secrets);
+  const idsToRemove = allSecrets.filter((s) => s.providerId === providerId).map((s) => s.secretReference.id);
+  secretsAdapter.removeMany(state.secrets, idsToRemove);
+}
+
+function captureSnapshot(state: SecretsManagerState, providerId: string): Record<string, SecretSnapshot> {
+  const allSecrets = secretsAdapter.getSelectors().selectAll(state.secrets);
+  const providerSecrets = allSecrets.filter((s) => s.providerId === providerId);
+  const snapshot: Record<string, SecretSnapshot> = {};
+  for (const s of providerSecrets) {
+    const ref = s.secretReference as AwsSecretValue["secretReference"];
+    snapshot[s.secretReference.id] = {
+      alias: s.secretReference.alias,
+      identifier: ref.identifier ?? "",
+      version: String(ref.version ?? ""),
+    };
+  }
+  return snapshot;
+}
+
+export const secretsManagerSlice = createSlice({
+  name: SECRETS_MANAGER_SLICE_NAME,
+  initialState,
+  reducers: {
+    setAllProviders(state, action: PayloadAction<SecretProviderMetadata[]>) {
+      providersAdapter.setAll(state.providers, action.payload);
+    },
+    upsertProvider(state, action: PayloadAction<SecretProviderMetadata>) {
+      providersAdapter.upsertOne(state.providers, action.payload);
+    },
+    removeProvider(state, action: PayloadAction<string>) {
+      providersAdapter.removeOne(state.providers, action.payload);
+    },
+    unsafePatchProvider(
+      state,
+      action: PayloadAction<{ id: string; patcher: (provider: SecretProviderMetadata) => void }>
+    ) {
+      const provider = state.providers.entities[action.payload.id];
+      if (provider) {
+        action.payload.patcher(provider);
+      }
+    },
+
+    setSelectedProviderId(state, action: PayloadAction<string | null>) {
+      state.selectedProviderId = action.payload;
+      state.secretsSnapshot = {};
+    },
+
+    upsertSecrets(state, action: PayloadAction<SecretValue[]>) {
+      secretsAdapter.upsertMany(state.secrets, action.payload);
+    },
+    setSecretsForProvider(state, action: PayloadAction<{ providerId: string; secrets: SecretValue[] }>) {
+      const { providerId, secrets } = action.payload;
+      removeSecretsForProvider(state, providerId);
+      secretsAdapter.upsertMany(state.secrets, secrets);
+      state.secretsSnapshot = captureSnapshot(state, providerId);
+    },
+    removeSecret(state, action: PayloadAction<string>) {
+      secretsAdapter.removeOne(state.secrets, action.payload);
+      delete state.secretsSnapshot[action.payload];
+    },
+    removeSecrets(state, action: PayloadAction<string[]>) {
+      secretsAdapter.removeMany(state.secrets, action.payload);
+      for (const id of action.payload) {
+        delete state.secretsSnapshot[id];
+      }
+    },
+
+    addSecretEntry(state, action: PayloadAction<{ providerId: string }>) {
+      const { providerId } = action.payload;
+      const stub: AwsSecretValue = {
+        type: SecretProviderType.AWS_SECRETS_MANAGER,
+        providerId,
+        secretReference: {
+          id: crypto.randomUUID(),
+          type: SecretProviderType.AWS_SECRETS_MANAGER,
+          alias: "",
+          identifier: "",
+        },
+        fetchedAt: 0,
+        name: "",
+        value: "",
+        ARN: "",
+        versionId: "",
+      };
+      secretsAdapter.addOne(state.secrets, stub);
+    },
+
+    removeSecretEntry(state, action: PayloadAction<{ providerId: string; secretRefId: string }>) {
+      secretsAdapter.removeOne(state.secrets, action.payload.secretRefId);
+    },
+
+    unsafePatchSecret(state, action: PayloadAction<{ id: string; patcher: (secret: SecretValue) => void }>) {
+      const secret = state.secrets.entities[action.payload.id];
+      if (secret) {
+        action.payload.patcher(secret);
+      }
+    },
+  },
+  extraReducers: (builder) => {
+    builder
+      .addCase(fetchAndSaveSecretsForProvider.pending, (state) => {
+        state.fetchStatus = "loading";
+      })
+      .addCase(fetchAndSaveSecretsForProvider.fulfilled, (state, action) => {
+        state.fetchStatus = "succeeded";
+        const { providerId } = action.meta.arg;
+        const { secrets, errors, validationErrors } = action.payload;
+
+        removeSecretsForProvider(state, providerId);
+        secretsAdapter.upsertMany(state.secrets, secrets);
+        state.secretsSnapshot = captureSnapshot(state, providerId);
+
+        const errorMap: Record<string, string> = {};
+        for (const err of errors) {
+          errorMap[err.secretRefId] = err.message;
+        }
+        state.fetchErrors = errorMap;
+        state.validationErrors = validationErrors;
+      })
+      .addCase(fetchAndSaveSecretsForProvider.rejected, (state) => {
+        state.fetchStatus = "failed";
+      })
+      .addCase(listSecrets.pending, (state) => {
+        state.fetchStatus = "loading";
+      })
+      .addCase(listSecrets.fulfilled, (state, action) => {
+        state.fetchStatus = "succeeded";
+        const providerId = action.meta.arg;
+
+        removeSecretsForProvider(state, providerId);
+        secretsAdapter.upsertMany(state.secrets, action.payload);
+        state.secretsSnapshot = captureSnapshot(state, providerId);
+      })
+      .addCase(listSecrets.rejected, (state) => {
+        state.fetchStatus = "failed";
+      });
+  },
+});
+
+export const secretsManagerActions = secretsManagerSlice.actions;
+export const secretsManagerReducer = secretsManagerSlice.reducer;
+
+const secretsManagerPersistConfig = {
+  key: "secrets_manager",
+  storage,
+  whitelist: ["selectedProviderId"],
+};
+
+export const secretsManagerReducerWithPersist = persistReducer(
+  secretsManagerPersistConfig,
+  secretsManagerSlice.reducer
+);

diff --git a/app/src/features/apiClient/slices/secrets-manager/thunks.ts b/app/src/features/apiClient/slices/secrets-manager/thunks.ts
new file mode 100644
index 0000000000000000000000000000000000000000..b4677d19b518f571fb0511403ebd4bd5b24d6e9c
--- /dev/null
+++ b/app/src/features/apiClient/slices/secrets-manager/thunks.ts
@@ -0,0 +1,332 @@
+import { createAsyncThunk } from "@reduxjs/toolkit";
+import {
+  SecretProviderMetadata,
+  SecretValue,
+  AwsSecretValue,
+  SecretReference,
+  SecretProviderType,
+} from "@requestly/shared/types/entities/secretsManager";
+import { notification } from "antd";
+import { secretsManagerService, toSecretProviderConfig, SecretFetchError } from "services/secretsManagerService";
+import { ProviderData } from "features/settings/secrets-manager/context/SecretsModalsContext";
+import { selectSelectedProviderId, selectAllSecretProviders, selectSecretsByProviderId } from "./selectors";
+import { secretsManagerActions } from "./slice";
+import { secretVariables } from "lib/secret-variables";
+import { SECRETS_MANAGER_SLICE_NAME } from "../common/constants";
+import { toast } from "utils/Toast";
+import {
+  trackSecretManagerProviderAdded,
+  trackSecretManagerProviderAddFailed,
+  trackSecretManagerSecretsFetched,
+  trackSecretManagerSecretsFetchFailed,
+  trackSecretManagerProviderDeleted,
+} from "features/settings/secrets-manager/analytics";
+
+type RootState = { secretsManager: import("./types").SecretsManagerState };
+
+export const fetchSecretProviders = createAsyncThunk<
+  SecretProviderMetadata[],
+  void,
+  { rejectValue: string; state: RootState }
+>(`${SECRETS_MANAGER_SLICE_NAME}/fetchProviders`, async (_, { rejectWithValue, dispatch, getState }) => {
+  const result = await secretsManagerService.listProviders();
+
+  if (result.type === "error") {
+    return rejectWithValue(result.error.message);
+  }
+
+  if (result.data.length > 0) {
+    dispatch(secretsManagerActions.setAllProviders(result.data));
+    const state = getState();
+    const activeProviderId = selectSelectedProviderId(state);
+
+    if (!activeProviderId || !result.data.some((p) => p.id === activeProviderId)) {
+      const firstProvider = result.data[0]!;
+      dispatch(secretsManagerActions.setSelectedProviderId(firstProvider.id));
+      await dispatch(listSecrets(firstProvider.id)).unwrap();
+    }
+  } else {
+    dispatch(secretsManagerActions.setAllProviders([]));
+    dispatch(secretsManagerActions.setSelectedProviderId(null));
+    secretVariables.updateSourceFromSecrets([]);
+  }
+
+  return result.data;
+});
+
+export const listSecrets = createAsyncThunk<SecretValue[], string, { rejectValue: string; state: RootState }>(
+  `${SECRETS_MANAGER_SLICE_NAME}/listSecrets`,
+  async (providerId, { rejectWithValue }) => {
+    const result = await secretsManagerService.listSecrets(providerId);
+    if (result.type === "error") {
+      return rejectWithValue(result.error.message);
+    }
+
+    // Redux state updation is done in the extraReducers of the slice
+
+    secretVariables.updateSourceFromSecrets(result.data as AwsSecretValue[]);
+    return result.data;
+  }
+);
+
+export const fetchAndSaveSecretsForProvider = createAsyncThunk<
+  {
+    secrets: SecretValue[];
+    errors: SecretFetchError[];
+    validationErrors: Record<string, { alias?: string; identifier?: string }>;
+  },
+  { providerId: string },
+  { rejectValue: string; state: RootState }
+>(
+  `${SECRETS_MANAGER_SLICE_NAME}/fetchAndSaveSecretsForProvider`,
+  async ({ providerId }, { getState, rejectWithValue }) => {
+    const state = getState();
+    const allProviderSecrets = selectSecretsByProviderId(state)(providerId);
+    const providerType = SecretProviderType.AWS_SECRETS_MANAGER;
+
+    // Rows where both alias and identifier are empty are silently ignored
+    const nonBlankSecrets = allProviderSecrets.filter((s) => {
+      const alias = (s.secretReference.alias ?? "").trim();
+      const identifier = ((s as AwsSecretValue).secretReference.identifier ?? "").trim();
+      return alias !== "" || identifier !== "";
+    });
+
+    const secretRefs = nonBlankSecrets.map((s) => s.secretReference);
+
+    // Frontend validation — runs before the IPC call
+    const aliasCounts = new Map<string, number>();
+    for (const s of nonBlankSecrets) {
+      const alias = (s.secretReference.alias ?? "").trim();
+      if (alias) {
+        aliasCounts.set(alias, (aliasCounts.get(alias) ?? 0) + 1);
+      }
+    }
+
+    const validationMap: Record<string, { alias?: string; identifier?: string }> = {};
+    for (const s of nonBlankSecrets) {
+      const refId = s.secretReference.id;
+      const alias = (s.secretReference.alias ?? "").trim();
+      const identifier = ((s as AwsSecretValue).secretReference.identifier ?? "").trim();
+
+      if (!alias) {
+        validationMap[refId] = { ...validationMap[refId], alias: "Alias is required" };
+      } else if ((aliasCounts.get(alias) ?? 0) > 1) {
+        validationMap[refId] = { ...validationMap[refId], alias: `Alias "${alias}" is duplicated` };
+      }
+
+      if (!identifier) {
+        validationMap[refId] = { ...validationMap[refId], identifier: "ARN/Secret name is required" };
+      }
+    }
+
+    const invalidRefIds = new Set(Object.keys(validationMap));
+    const validRefs = secretRefs.filter((ref) => !invalidRefIds.has(ref.id));
+
+    const fetchStartTime = Date.now();
+    const fetchAndSaveSecretsResult = await secretsManagerService.fetchAndSaveSecrets(providerId, validRefs);
+    if (fetchAndSaveSecretsResult.type === "error") {
+      trackSecretManagerSecretsFetchFailed(
+        providerType,
+        fetchAndSaveSecretsResult.error.code,
+        fetchAndSaveSecretsResult.error.message,
+        "user_action"
+      );
+
+      return rejectWithValue(fetchAndSaveSecretsResult.error.message);
+    }
+
+    const { secrets, errors: backendErrors } = fetchAndSaveSecretsResult.data;
+
+    const totalErrorCount = Object.keys(validationMap).length + backendErrors.length;
+    if (totalErrorCount > 0) {
+      const firstBackendError = backendErrors[0];
+      const firstValidationEntry = Object.entries(validationMap)[0];
+      const singleErrorMessage =
+        totalErrorCount === 1
+          ? firstBackendError?.message ?? firstValidationEntry?.[1]?.alias ?? firstValidationEntry?.[1]?.identifier
+          : undefined;
+
+      notification.warn({
+        message: "Some secrets failed to fetch",
+        description: singleErrorMessage ?? `${totalErrorCount} secrets failed to fetch.`,
+        placement: "bottomRight",
+        className: "add-secrets-provider-notification",
+      });
+    } else {
+      toast.success("Successfully fetched secrets");
+    }
+
+    const erroredRefIds = new Set([...Object.keys(validationMap), ...backendErrors.map((e) => e.secretRefId)]);
+    const originalErroredRows = nonBlankSecrets.filter((s) => erroredRefIds.has(s.secretReference.id));
+    const allSecretsForRedux = [...secrets, ...originalErroredRows];
+
+    secretVariables.updateSourceFromSecrets(secrets as AwsSecretValue[]);
+
+    const fetchDurationMs = Date.now() - fetchStartTime;
+    if (totalErrorCount === 0) {
+      trackSecretManagerSecretsFetched(providerType, secrets.length, fetchDurationMs, "user_action");
+    }
+
+    return { secrets: allSecretsForRedux, errors: backendErrors, validationErrors: validationMap };
+  }
+);
+
+export const saveProvider = createAsyncThunk<
+  string,
+  { formData: ProviderData; existingId?: string; mode: "add" | "edit" },
+  { rejectValue: string; state: RootState }
+>(
+  `${SECRETS_MANAGER_SLICE_NAME}/saveProvider`,
+  async ({ formData, existingId, mode }, { dispatch, rejectWithValue }) => {
+    const config = toSecretProviderConfig(formData, existingId);
+
+    const result = await secretsManagerService.setProviderConfig(config);
+    if (result.type === "error") {
+      trackSecretManagerProviderAddFailed(
+        SecretProviderType.AWS_SECRETS_MANAGER,
+        result.error.code,
+        result.error.message,
+        "save"
+      );
+      return rejectWithValue(result.error.message);
+    }
+
+    await dispatch(fetchSecretProviders()).unwrap();
+    dispatch(secretsManagerActions.setSelectedProviderId(config.id));
+
+    if (mode === "add") {
+      trackSecretManagerProviderAdded(SecretProviderType.AWS_SECRETS_MANAGER, formData.instanceName, 0);
+    }
+
+    return config.id;
+  }
+);
+
+let isSubscriptionRegistered = false;
+export const initAndSubscribeSecretsManager = createAsyncThunk<void, string, { rejectValue: string; state: RootState }>(
+  `${SECRETS_MANAGER_SLICE_NAME}/init`,
+  async (userId, { dispatch, getState, rejectWithValue, signal }) => {
+    isSubscriptionRegistered = false;
+    const initResult = await secretsManagerService.init(userId);
+
+    if (initResult.type === "error") {
+      return rejectWithValue(initResult.error.message);
+    }
+
+    if (signal.aborted) {
+      return;
+    }
+
+    if (!isSubscriptionRegistered) {
+      isSubscriptionRegistered = true;
+      secretsManagerService.subscribeToProvidersChange(() => {
+        dispatch(fetchSecretProviders());
+      });
+    }
+
+    await dispatch(fetchSecretProviders()).unwrap();
+
+    if (signal.aborted) {
+      return;
+    }
+
+    const state = getState();
+    const activeProviderId = selectSelectedProviderId(state);
+
+    if (activeProviderId) {
+      await dispatch(listSecrets(activeProviderId)).unwrap();
+    }
+  }
+);
+
+export const deleteProvider = createAsyncThunk<void, string, { rejectValue: string; state: RootState }>(
+  `${SECRETS_MANAGER_SLICE_NAME}/deleteProvider`,
+  async (providerId, { dispatch, rejectWithValue, getState }) => {
+    const state = getState();
+    const providerType = SecretProviderType.AWS_SECRETS_MANAGER;
+    const secretsCount = selectSecretsByProviderId(state)(providerId).length;
+
+    const result = await secretsManagerService.removeProviderConfig(providerId);
+    if (result.type === "error") {
+      return rejectWithValue(result.error.message);
+    }
+    dispatch(secretsManagerActions.removeProvider(providerId));
+    trackSecretManagerProviderDeleted(providerType, secretsCount);
+    const providers = selectAllSecretProviders(state);
+    const nextProvider = providers.find((p) => p.id !== providerId);
+
+    dispatch(deleteAllSecretsForProvider({ providerId })).unwrap();
+
+    if (nextProvider) {
+      notification.info({
+        message: `"${nextProvider.name}" is now active`,
+        description: "Fetch secrets to continue using them in requests",
+        placement: "bottomRight",
+      });
+      dispatch(secretsManagerActions.setSelectedProviderId(nextProvider.id));
+      await dispatch(listSecrets(nextProvider.id)).unwrap();
+    } else {
+      dispatch(secretsManagerActions.setSelectedProviderId(null));
+    }
+  }
+);
+
+export const deleteSecret = createAsyncThunk<
+  void,
+  { providerId: string; secretReference: SecretReference },
+  { rejectValue: string; state: RootState }
+>(
+  `${SECRETS_MANAGER_SLICE_NAME}/deleteSecret`,
+  async ({ providerId, secretReference }, { dispatch, rejectWithValue, getState }) => {
+    const result = await secretsManagerService.removeSecretValue(providerId, secretReference);
+    if (result.type === "error") {
+      return rejectWithValue(result.error.message);
+    }
+    dispatch(secretsManagerActions.removeSecret(secretReference.id));
+    toast.success("Secret deleted");
+
+    const state = getState();
+    const secretsForProvider = selectSecretsByProviderId(state)(providerId);
+    if (secretsForProvider.length === 0) {
+      secretVariables.updateSourceFromSecrets([]);
+    } else {
+      secretVariables.updateSourceFromSecrets(secretsForProvider as AwsSecretValue[]);
+    }
+  }
+);
+
+export const deleteAllSecretsForProvider = createAsyncThunk<
+  void,
+  { providerId: string },
+  { rejectValue: string; state: RootState }
+>(
+  `${SECRETS_MANAGER_SLICE_NAME}/deleteAllSecretsForProvider`,
+  async ({ providerId }, { dispatch, rejectWithValue, getState }) => {
+    const state = getState();
+    const allSecrets = selectSecretsByProviderId(state)(providerId);
+
+    const secretsToDelete = allSecrets.filter((s) => s.providerId === providerId);
+
+    const secretRefsToDelete = secretsToDelete.map((s) => s.secretReference);
+    const result = await secretsManagerService.removeSecretValues(
+      secretRefsToDelete.map((ref) => ({ providerId, ref }))
+    );
+    if (result.type === "error") {
+      return rejectWithValue(result.error.message);
+    }
+    dispatch(secretsManagerActions.removeSecrets(secretRefsToDelete.map((s) => s.id)));
+
+    secretVariables.updateSourceFromSecrets([]);
+  }
+);
+
+export const revertDirtyChanges = createAsyncThunk(
+  `secretsManager/revertDirtyChanges`,
+  async (_, { dispatch, getState }) => {
+    const state = getState() as RootState;
+    const providerId = selectSelectedProviderId(state);
+    if (providerId) {
+      await dispatch(listSecrets(providerId));
+    }
+  }
+);

