+                  <span className="migration-block-modal__platform-row-label">
+                    {isPlatformProbed && platform ? "Other platforms" : "Choose platform"}
+                  </span>
+                  {secondaryPlatforms.map((p) => {
+                    const Icon = PLATFORM_ICONS[p];
