@@ -0,0 +1,59 @@
+import { capitalize } from '@rocket.chat/string-helpers';
+import { isTruthy } from '@rocket.chat/tools';
+import type { Strategy } from 'passport';
+
+import { OAuthConfigs } from './oauthConfigs';
+import { type ICachedSettings } from '../../../app/settings/server/CachedSettings';
+
+export type OAuthServiceConfig = {
+	provider: string;
+	strategy: new (...args: any[]) => Strategy;
+	clientId: string;
+	clientSecret: string;
+	scope?: string[];
+};
+
+export const createOAuthServiceConfig = (settings: ICachedSettings, services: string[]): OAuthServiceConfig[] => {
+	return services
+		.map((service) => {
+			if (!OAuthConfigs[service]) {
+				return;
+			}
+
+			if (service === 'github_enterprise') {
+				const clientId = settings.get<string>('Accounts_OAuth_GitHub_Enterprise_id');
+				const clientSecret = settings.get<string>('Accounts_OAuth_GitHub_Enterprise_secret');
+				const serverUrl = settings.get<string>('API_GitHub_Enterprise_URL');
+
+				if (!clientId || !clientSecret || !serverUrl) {
+					return;
+				}
+
+				return {
+					provider: service,
+					clientId,
+					clientSecret,
+					authorizationURL: `${serverUrl}/login/oauth/authorize`,
+					tokenURL: `${serverUrl}/login/oauth/access_token`,
+					userProfileURL: `${serverUrl}/api/v3/user`,
+					strategy: OAuthConfigs.github_enterprise.strategy,
+					scope: OAuthConfigs.github_enterprise.scope,
+				};
+			}
+
+			const clientId = settings.get<string>(`Accounts_OAuth_${capitalize(service)}_id`);
+			const clientSecret = settings.get<string>(`Accounts_OAuth_${capitalize(service)}_secret`);
+
+			if (!clientId || !clientSecret) {
+				return;
+			}
+
+			return {
+				provider: service,
+				clientId,
+				clientSecret,
+				...OAuthConfigs[service],
+			};
+		})
+		.filter(isTruthy);
+};

diff --git a/apps/meteor/server/lib/oauth/getOAuthServices.ts b/apps/meteor/server/lib/oauth/getOAuthServices.ts
new file mode 100644
index 0000000000000000000000000000000000000000..7a431982d9f714c51697b03a86f2a26aabd521ae
--- /dev/null
+++ b/apps/meteor/server/lib/oauth/getOAuthServices.ts
@@ -0,0 +1,34 @@
+import { isTruthy } from '@rocket.chat/tools';
+
+import { OAuthConfigs } from './oauthConfigs';
+import { type ICachedSettings } from '../../../app/settings/server/CachedSettings';
+
+export const getOAuthServices = (settings: ICachedSettings) => {
+	const services = settings.getByRegexp(/^(Accounts_OAuth_|Accounts_OAuth_Custom-)[a-z0-9_]+$/i);
+	const filteredServices = services.filter(([, value]) => typeof value === 'boolean' && value === true);
+	return filteredServices
+		.map(([key, value]) => {
+			if (!value) {
+				return;
+			}
+
+			let serviceName = key.replace('Accounts_OAuth_', '');
+			if (serviceName === 'Meteor') {
+				serviceName = 'meteor-developer';
+			}
+
+			if (/Accounts_OAuth_Custom-/.test(key)) {
+				return;
+			}
+
+			const serviceKey = serviceName.toLowerCase();
+
+			const oauthConfig = OAuthConfigs[serviceKey];
+			if (!oauthConfig) {
+				return;
+			}
+
+			return serviceKey;
+		})
+		.filter(isTruthy);
+};

