+
+const commonExtensionFields = {
+  id: z.string(),
+  name: localizedStringSchema,
+  description: localizedStringSchema.nullable(),
+  logo: logoSchema,
+  installed: z.boolean().optional(),
+  disabled: z.boolean().optional(),
