+const extractComments = (str: string): { text: string; comments: string[] } => {
+  const comments: string[] = [];
+  let result = '';
+  let depth = 0;
+  let currentComment = '';
+  let inQuotes = false;
+  let escape = false;
+
+  for (const char of str) {
+    if (escape) {
