diff --git a/integrations/zoom/src/setup/handler.ts b/integrations/zoom/src/setup/handler.ts
new file mode 100644
index 0000000000000000000000000000000000000000..82fcd35a88a2132a0e2c655eefcf064a6ad3f7b3
--- /dev/null
+++ b/integrations/zoom/src/setup/handler.ts
@@ -0,0 +1,117 @@
+import { Request, RuntimeError } from '@botpress/sdk'
+import axios from 'axios'
+import crypto from 'crypto'
+import { ZoomClient } from '../client'
+import { zoomWebhookSchema, TranscriptCompletedPayload } from '../types'
+import { cleanVtt } from '../utils'
+import * as bp from '.botpress'
+
+const handleTranscriptCompleted = async ({
+  payload,
+  config,
+  client,
+  logger,
+}: {
+  payload: TranscriptCompletedPayload
+  config: bp.configuration.Configuration
+  client: bp.Client
+  logger: bp.Logger
+}): Promise<{ status: number; body: string }> => {
+  try {
+    const allowedUserIds = config.allowedZoomUserIds
+    const hostId = payload.payload.object.host_id
+
+    if (!allowedUserIds.includes(hostId)) {
+      return { status: 200, body: 'Event ignored: userId not allowed' }
+    }
+
+    const zoomClient = new ZoomClient(config, logger)
+    const accessToken = await zoomClient.getAccessToken()
+    const meetingUUID = payload.payload.object.uuid
+
+    const response = await zoomClient.fetchTranscriptUrl(meetingUUID, accessToken)
+
+    if (!response) {
+      throw new RuntimeError('Transcript file not found after retries')
+    }
+
+    const { transcriptUrl, audioUrl } = response
+
+    const { data: vttText } = await axios.get<string>(transcriptUrl, {
+      headers: { Authorization: `Bearer ${accessToken}` },
+      responseType: 'text',
+      timeout: 30000,
+    })
+    const plainText = cleanVtt(vttText)
+
+    await client.createEvent({
+      type: 'transcriptReceived',
+      payload: {
+        meetingUUID,
+        hostId,
+        transcript: plainText,
+        audioUrl,
+        rawVtt: vttText,
+      },
+    })
+
+    logger.forBot().info(`Transcript processed successfully for meeting ${meetingUUID}`)
+    return { status: 200, body: 'Transcript processed.' }
+  } catch (err: unknown) {
+    const errorMsg = err instanceof Error ? err.message : 'Unknown error'
+    logger.forBot().error(`Transcript handler error: ${errorMsg}`)
+    return { status: 500, body: `Zoom handler error: ${errorMsg}` }
+  }
+}
+
+export const handler: bp.IntegrationProps['handler'] = async ({ req, ctx, client, logger }) => {
+  const config = ctx.configuration
+  const isSignatureValid = _isSignatureValid(req, config.secretToken)
+  if (!isSignatureValid) {
+    logger.forBot().warn('Request signature was invalid')
+    return { status: 401, body: 'Invalid signature' }
+  }
+
+  try {
+    const parsed = typeof req.body === 'string' ? JSON.parse(req.body) : req.body
+    const validation = zoomWebhookSchema.safeParse(parsed)
+    if (!validation.success) {
+      logger.forBot().error(`Invalid webhook body format: ${validation.error.message}`)
+      return { status: 400, body: 'Invalid request body format' }
+    }
+
+    const webhookBody = validation.data
+
+    if (webhookBody.event === 'endpoint.url_validation') {
+      const plainToken = webhookBody.payload.plainToken
+      const encryptedToken = crypto.createHmac('sha256', config.secretToken).update(plainToken).digest('hex')
+
+      return {
+        status: 200,
+        body: JSON.stringify({ plainToken, encryptedToken }),
+        headers: { 'Content-Type': 'application/json' },
+      }
+    }
+
+    if (webhookBody.event === 'recording.transcript_completed') {
+      return await handleTranscriptCompleted({ payload: webhookBody, config, client, logger })
+    }
+
+    return { status: 200, body: 'Event ignored.' }
+  } catch (error) {
+    const errorMsg = error instanceof Error ? error.message : 'Unknown error'
+    logger.forBot().error(`Webhook handler error: ${errorMsg}`)
+    return { status: 400, body: 'Invalid request' }
+  }
+}
+
+const _isSignatureValid = (req: Request, secret: string) => {
+  const timestamp = req.headers?.['x-zm-request-timestamp']
+  const signature = req.headers?.['x-zm-signature']
+  if (!timestamp || !signature) {
+    return false
+  }
+  const message = `v0:${timestamp}:${typeof req.body === 'string' ? req.body : JSON.stringify(req.body)}`
+  const expectedSig = 'v0=' + crypto.createHmac('sha256', secret).update(message).digest('hex')
+  return signature === expectedSig
+}

diff --git a/packages/common/src/html-dialogs/components/pages/form-dialog.tsx b/packages/common/src/html-dialogs/components/pages/form-dialog.tsx
new file mode 100644
index 0000000000000000000000000000000000000000..0eac37a78414db52b42c98e12c19d84da4c4d347
--- /dev/null
+++ b/packages/common/src/html-dialogs/components/pages/form-dialog.tsx
@@ -0,0 +1,209 @@
+import type { FormFieldDescriptor } from '../../../oauth-wizard/schema-to-fields'
+import MarkdownDiv from '../markdown-div'
+
+type FieldProps = { field: FormFieldDescriptor; fieldName: string; value?: string }
+
+const FieldDescription = ({ description }: { description?: string }) =>
+  description ? <div className="form-text">{description}</div> : null
+
+const FieldError = ({ error, inline }: { error?: string; inline?: boolean }) =>
+  error ? <div className={inline ? 'text-danger small mt-1' : 'invalid-feedback'}>{error}</div> : null
+
+const BooleanField = ({ field, fieldName, value }: FieldProps) => {
+  return (
+    <div className="form-check mb-3">
+      <input
+        type="checkbox"
+        className="form-check-input"
+        id={fieldName}
+        name={fieldName}
+        value="true"
+        checked={value === 'true'}
+        required={field.required}
+        disabled={field.disabled}
+      />
+      <label className="form-check-label" htmlFor={fieldName}>
+        {field.label}
+      </label>
+      <FieldDescription description={field.description} />
+      <FieldError error={field.error} inline />
+    </div>
+  )
+}
+
+const EnumField = ({ field, fieldName, value }: FieldProps) => {
+  const p = field.displayAsParams
+  const options = field.options ?? []
+
+  if (field.inputType === 'radio') {
+    return (
+      <div className="form-group mb-3">
+        <label className="form-label">{field.label}</label>
+        {options.map((opt) => (
+          <div key={opt.value} className="form-check">
+            <input
+              type="radio"
+              className="form-check-input"
+              id={`${fieldName}-${opt.value}`}
+              name={fieldName}
+              value={opt.value}
+              checked={value === opt.value}
+              required={field.required}
+              disabled={field.disabled}
+            />
+            <label className="form-check-label" htmlFor={`${fieldName}-${opt.value}`}>
+              {opt.label}
+            </label>
+          </div>
+        ))}
+        <FieldDescription description={field.description} />
+        <FieldError error={field.error} inline />
+      </div>
+    )
+  }
+
+  return (
+    <div className="form-group mb-3">
+      <label htmlFor={fieldName} className="form-label">
+        {field.label}
+      </label>
+      <select
+        className={`form-select${field.error ? ' is-invalid' : ''}`}
+        id={fieldName}
+        name={fieldName}
+        required={field.required}
+        disabled={field.disabled}
+        multiple={p.multiple as boolean | undefined}
+        size={p.size as number | undefined}
+      >
+        <option value="">{field.placeholder ?? 'Select...'}</option>
+        {options.map((opt) => (
+          <option key={opt.value} value={opt.value} selected={value === opt.value}>
+            {opt.label}
+          </option>
+        ))}
+      </select>
+      <FieldDescription description={field.description} />
+      <FieldError error={field.error} />
+    </div>
+  )
+}
+
+const TextField = ({ field, fieldName, value }: FieldProps) => {
+  const p = field.displayAsParams
+  return (
+    <div className="form-group mb-3">
+      <label htmlFor={fieldName} className="form-label">
+        {field.label}
+      </label>
+      <textarea
+        className={`form-control${field.error ? ' is-invalid' : ''}`}
+        id={fieldName}
+        name={fieldName}
+        placeholder={field.placeholder}
+        required={field.required}
+        disabled={field.disabled}
+        rows={p.rows as number | undefined}
+        cols={p.cols as number | undefined}
+        maxLength={p.maxLength as number | undefined}
+      >
+        {value}
+      </textarea>
+      <FieldDescription description={field.description} />
+      <FieldError error={field.error} />
+    </div>
+  )
+}
+
+const StringField = ({ field, fieldName, value }: FieldProps) => {
+  const p = field.displayAsParams
+  return (
+    <div className="form-group mb-3">
+      <label htmlFor={fieldName} className="form-label">
+        {field.label}
+      </label>
+      <input
+        type={field.inputType}
+        className={`form-control${field.error ? ' is-invalid' : ''}`}
+        id={fieldName}
+        name={fieldName}
+        placeholder={field.placeholder}
+        required={field.required}
+        disabled={field.disabled}
+        value={value}
+        min={p.min as string | number | undefined}
+        max={p.max as string | number | undefined}
+        step={(p.step ?? p.stepSize) as string | number | undefined}
+        pattern={p.pattern as string | undefined}
+        minLength={p.minLength as number | undefined}
+        maxLength={p.maxLength as number | undefined}
+      />
+      <FieldDescription description={field.description} />
+      <FieldError error={field.error} />
+    </div>
+  )
+}
+
+const FormField = ({ field, paramPrefix }: { field: FormFieldDescriptor; paramPrefix: string }) => {
+  const fieldName = `${paramPrefix}${field.name}`
+  const value = field.previousValue ?? field.defaultValue
+
+  switch (field.inputType) {
+    case 'checkbox':
+      return <BooleanField field={field} fieldName={fieldName} value={value} />
+    case 'radio':
+    case 'select':
+      return <EnumField field={field} fieldName={fieldName} value={value} />
+    case 'textarea':
+      return <TextField field={field} fieldName={fieldName} value={value} />
+    default:
+      return <StringField field={field} fieldName={fieldName} value={value} />
+  }
+}
+
+export default ({
+  pageTitle,
+  helpText,
+  formSubmitUrl,
+  formParamPrefix,
+  fields,
+  extraHiddenParams,
+}: {
+  pageTitle: string
+  helpText: string
+  formSubmitUrl: URL
+  formParamPrefix: string
+  fields: FormFieldDescriptor[]
+  extraHiddenParams: Record<string, string>
+}) => {
+  return (
+    <div className="d-flex justify-content-center align-items-center vh-100 overflow-hidden">
+      <div className="d-flex flex-column w-100 py-4 mh-100" style={{ maxWidth: 500 }}>
+        <div className="flex-shrink-0">
+          <h1 className="text-center">{pageTitle}</h1>
+          <MarkdownDiv>{helpText}</MarkdownDiv>
+        </div>
+        <form
+          className="flex-grow-1 px-1 overflow-auto"
+          id="wizard-form"
+          action={formSubmitUrl.href}
+          method="POST"
+          style={{ minHeight: 0 }}
+        >
+          {Object.entries(extraHiddenParams).map(([key, value]) => (
+            <input key={key} type="hidden" name={key} value={value} />
+          ))}
+          {fields
+            .filter((f) => !f.hidden)
+            .map((field) => (
+              <FormField key={field.name} field={field} paramPrefix={formParamPrefix} />
+            ))}
+
+          <button type="submit" className="btn btn-primary w-100 d-block">
+            Submit
+          </button>
+        </form>
+      </div>
+    </div>
+  )
+}

