+  // Group consecutive cards with identical shapes
+  type Run = { fingerprint: string; items: Carousel['items'] }
+  const runs: Run[] = []
+  for (let i = 0; i < items.length; i++) {
+    const fingerprint = shapes[i]!.join('')
