diff --git a/src/pages/api/admin/users.ts b/src/pages/api/admin/users.ts
new file mode 100644
index 0000000000000000000000000000000000000000..d16895b745f8f242b9c4e1b9804edc3b5a5e0922
--- /dev/null
+++ b/src/pages/api/admin/users.ts
@@ -0,0 +1,53 @@
+import { canViewUsers } from 'lib/auth';
+import { useAuth, useValidate } from 'lib/middleware';
+import { NextApiRequestQueryBody, Role, SearchFilter, User } from 'lib/types';
+import { pageInfo } from 'lib/schema';
+import { NextApiResponse } from 'next';
+import { methodNotAllowed, ok, unauthorized } from 'next-basics';
+import { getUsers } from 'queries';
+import * as yup from 'yup';
+
+export interface UsersRequestQuery extends SearchFilter {}
+export interface UsersRequestBody {
+  username: string;
+  password: string;
+  id: string;
+  role: Role;
+}
+
+const schema = {
+  GET: yup.object().shape({
+    ...pageInfo,
+  }),
+  POST: yup.object().shape({
+    username: yup.string().max(255).required(),
+    password: yup.string().required(),
+    id: yup.string().uuid(),
+    role: yup
+      .string()
+      .matches(/admin|user|view-only/i)
+      .required(),
+  }),
+};
+
+export default async (
+  req: NextApiRequestQueryBody<UsersRequestQuery, UsersRequestBody>,
+  res: NextApiResponse<User[] | User>,
+) => {
+  await useAuth(req, res);
+  await useValidate(schema, req, res);
+
+  if (req.method === 'GET') {
+    if (!(await canViewUsers(req.auth))) {
+      return unauthorized(res);
+    }
+
+    const { page, query, pageSize } = req.query;
+
+    const users = await getUsers({ page, query, pageSize: +pageSize || undefined });
+
+    return ok(res, users);
+  }
+
+  return methodNotAllowed(res);
+};

